// Secure Express Application
// Enhanced with security best practices

require('dotenv').config();
require('express-async-errors');

const express = require('express');
const app = express();

// Security middleware
const { securityHeaders, limiter, corsOptions, cors } = require('./security-middleware');
const { errorHandler, notFoundHandler } = require('./error-handler');
const { validateRequest, querySchema, sanitizeInput } = require('./validation');

// Apply security middleware
app.use(securityHeaders);
app.use(cors(corsOptions));
app.use(express.json({ limit: '10kb' })); // Limit request body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Apply rate limiting to all routes
app.use(limiter);

// Basic request logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log({
      timestamp: new Date().toISOString(),
      method: req.method,
      url: req.originalUrl,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent'),
    });
  });
  next();
});

// Health endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Secure users endpoint with input validation
app.get('/users', 
  sanitizeInput(['search', 'page', 'limit']),
  validateRequest(querySchema),
  (req, res) => {
    const { page = 1, limit = 10 } = req.query;

    // Mock user data (in real app, this would come from database)
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        createdAt: new Date('2024-01-01').toISOString()
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        createdAt: new Date('2024-01-02').toISOString()
      },
    ].slice((page - 1) * limit, page * limit);

    // Sanitize sensitive data before sending
    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      // Don't expose email in response by default
      // email: user.email, // Only include if necessary
      createdAt: user.createdAt,
    }));

    res.json({
      data: sanitizedUsers,
      pagination: {
        page: parseInt(page),
        limit: parseInt(limit),
        total: 2,
        totalPages: Math.ceil(2 / limit),
      },
    });
  }
);

// Example authentication middleware (stub - implement properly)
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.replace('Bearer ', '');

  if (!token) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Authentication token required',
    });
  }

  // In real implementation, verify JWT token here
  try {
    // const decoded = jwt.verify(token, process.env.JWT_SECRET);
    // req.user = decoded;
    next();
  } catch (error) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Invalid or expired token',
    });
  }
};

// Protected admin endpoint example
app.get('/admin/users', authenticate, (req, res) => {
  // Only return full user data to authenticated admin users
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      role: 'user',
      createdAt: new Date('2024-01-01').toISOString()
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
      role: 'admin',
      createdAt: new Date('2024-01-02').toISOString()
    },
  ];

  res.json({ data: users });
});

// 404 handler for undefined routes
app.use(notFoundHandler);

// Error handler (must be last middleware)
app.use(errorHandler);

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

app.listen(PORT, HOST, () => {
  console.log(`Secure server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Health endpoint: http://${HOST}:${PORT}/health`);
});

module.exports = app;

