// security.test.js - Security-focused tests
const request = require('supertest');
const app = require('./app');

describe('Security Tests', () => {
  describe('Security Headers', () => {
    test('should include security headers', async () => {
      const response = await request(app).get('/health');

      expect(response.headers).toHaveProperty('x-content-type-options');
      expect(response.headers['x-content-type-options']).toBe('nosniff');

      expect(response.headers).toHaveProperty('x-frame-options');
      expect(response.headers).toHaveProperty('referrer-policy');
    });

    test('should have Content Security Policy', async () => {
      const response = await request(app).get('/health');
      expect(response.headers).toHaveProperty('content-security-policy');
    });
  });

  describe('Rate Limiting', () => {
    test('should enforce rate limiting', async () => {
      const requests = Array(105).fill().map(() => 
        request(app).get('/health')
      );

      const responses = await Promise.all(requests);
      const rateLimitedResponses = responses.filter(r => r.status === 429);

      expect(rateLimitedResponses.length).toBeGreaterThan(0);
    }, 30000); // Extended timeout for rate limiting test
  });

  describe('Input Validation', () => {
    test('should reject malformed query parameters', async () => {
      const response = await request(app)
        .get('/users')
        .query({ page: 'invalid', limit: 'not-a-number' });

      expect(response.status).toBe(400);
      expect(response.body).toHaveProperty('error', 'Validation failed');
    });

    test('should sanitize user input', async () => {
      const response = await request(app)
        .get('/users')
        .query({ search: '<script>alert("xss")</script>' });

      // The search parameter should be sanitized
      expect(response.status).toBe(200);
    });
  });

  describe('Authentication & Authorization', () => {
    test('should require authentication for admin endpoint', async () => {
      const response = await request(app).get('/admin/users');
      expect(response.status).toBe(401);
      expect(response.body).toHaveProperty('error', 'Unauthorized');
    });

    test('should accept valid bearer token', async () => {
      // This would test with a valid JWT token
      const response = await request(app)
        .get('/admin/users')
        .set('Authorization', 'Bearer valid-token-here');

      // In real implementation, this would check for 200 OK
      // For now, just verify the endpoint exists
      expect(response.status).toBe(401); // Because our token isn't valid
    });
  });

  describe('Error Handling', () => {
    test('should not expose stack traces in production', async () => {
      // Mock environment to production
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      // Create a route that throws error
      const testApp = require('express')();
      const { errorHandler } = require('./error-handler');

      testApp.get('/error-test', () => {
        throw new Error('Test error');
      });
      testApp.use(errorHandler);

      const response = await request(testApp).get('/error-test');

      expect(response.body).toHaveProperty('error', 'Internal Server Error');
      expect(response.body.message).not.toContain('Test error');

      process.env.NODE_ENV = originalEnv;
    });

    test('should return 404 for undefined routes', async () => {
      const response = await request(app).get('/undefined-route');
      expect(response.status).toBe(404);
      expect(response.body).toHaveProperty('error', 'Not Found');
    });
  });

  describe('Sensitive Data Protection', () => {
    test('should not expose sensitive user data', async () => {
      const response = await request(app).get('/users');

      // Regular users endpoint should not expose email
      const user = response.body.data[0];
      expect(user).not.toHaveProperty('email');
      expect(user).toHaveProperty('name');
      expect(user).toHaveProperty('id');
      expect(user).toHaveProperty('createdAt');
    });

    test('admin endpoint should expose full data', async () => {
      // This would test authenticated admin access
      // For now, just verify the endpoint structure
      const response = await request(app)
        .get('/admin/users')
        .set('Authorization', 'Bearer admin-token');

      // In full implementation, admin endpoint would return full data
      expect(response.status).toBe(401); // Not authenticated
    });
  });

  describe('CORS Configuration', () => {
    test('should have proper CORS headers', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'http://localhost:3000');

      expect(response.headers).toHaveProperty('access-control-allow-origin');
    });

    test('should reject unauthorized origins', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'http://malicious-site.com');

      // In production, this should reject unauthorized origins
      if (process.env.NODE_ENV === 'production') {
        expect(response.headers['access-control-allow-origin']).not.toBe('http://malicious-site.com');
      }
    });
  });

  describe('Request Size Limiting', () => {
    test('should reject oversized request bodies', async () => {
      const largeBody = 'x'.repeat(15 * 1024); // 15KB > 10KB limit

      const response = await request(app)
        .post('/some-endpoint') // You'd need to create a POST endpoint to test this
        .send({ data: largeBody })
        .set('Content-Type', 'application/json');

      // The request should be rejected or truncated
      expect(response.status).not.toBe(200);
    });
  });
});

// Injection attack tests
describe('Injection Protection', () => {
  test('should be protected against SQL injection', async () => {
    const response = await request(app)
      .get('/users')
      .query({ search: "'; DROP TABLE users; --" });

    // Should handle the input safely (sanitized or rejected)
    expect(response.status).toBe(200);
  });

  test('should handle NoSQL injection attempts', async () => {
    const response = await request(app)
      .get('/users')
      .query({ search: { $ne: null } });

    // Should handle object injection attempts
    expect(response.status).toBe(400); // Should reject object in query
  });
});

