// config.js - Secure environment configuration
const path = require('path');
const fs = require('fs');

class Config {
  constructor() {
    this.env = this.getEnvironment();
    this.secrets = this.loadSecrets();
    this.validateSecrets();
  }

  getEnvironment() {
    const env = process.env.NODE_ENV || 'development';
    const validEnvs = ['development', 'test', 'staging', 'production'];

    if (!validEnvs.includes(env)) {
      throw new Error(`Invalid NODE_ENV: ${env}. Must be one of: ${validEnvs.join(', ')}`);
    }

    return env;
  }

  loadSecrets() {
    // For production: use secrets manager or environment variables
    if (this.env === 'production') {
      return this.loadProductionSecrets();
    }

    // For development/test: load from .env file with explicit path
    const envFile = path.join(__dirname, `.env.${this.env}`);
    const defaultEnvFile = path.join(__dirname, '.env');

    // Check if environment-specific file exists
    if (fs.existsSync(envFile)) {
      require('dotenv').config({ path: envFile });
      console.log(`Loaded environment from: ${envFile}`);
    } else if (fs.existsSync(defaultEnvFile)) {
      require('dotenv').config({ path: defaultEnvFile });
      console.log(`Loaded environment from: ${defaultEnvFile}`);
    } else {
      console.warn(`No .env file found for ${this.env} environment`);
    }

    return this.parseSecrets();
  }

  loadProductionSecrets() {
    // In production, prefer environment variables over files
    const secrets = this.parseSecrets();

    // If using AWS Secrets Manager, HashiCorp Vault, etc.
    if (process.env.USE_SECRETS_MANAGER === 'true') {
      return this.loadFromSecretsManager();
    }

    return secrets;
  }

  parseSecrets() {
    return {
      // Server configuration
      port: parseInt(process.env.PORT) || 3000,
      host: process.env.HOST || '0.0.0.0',
      nodeEnv: this.env,

      // Database
      database: {
        url: process.env.DATABASE_URL,
        maxConnections: parseInt(process.env.DB_MAX_CONNECTIONS) || 10,
        ssl: process.env.DB_SSL === 'true',
      },

      // Authentication
      auth: {
        jwtSecret: process.env.JWT_SECRET,
        jwtExpiry: process.env.JWT_EXPIRY || '24h',
        refreshTokenExpiry: process.env.REFRESH_TOKEN_EXPIRY || '7d',
        bcryptRounds: parseInt(process.env.BCRYPT_ROUNDS) || 12,
      },

      // External APIs
      apis: {
        stripe: {
          secretKey: process.env.STRIPE_SECRET_KEY,
          publishableKey: process.env.STRIPE_PUBLISHABLE_KEY,
        },
        aws: {
          accessKeyId: process.env.AWS_ACCESS_KEY_ID,
          secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
          region: process.env.AWS_REGION || 'us-east-1',
        },
        anthropic: {
          apiKey: process.env.ANTHROPIC_API_KEY,
        },
      },

      // Monitoring
      monitoring: {
        logfireToken: process.env.LOGFIRE_TOKEN,
        sentryDsn: process.env.SENTRY_DSN,
      },

      // Feature flags
      features: {
        enableRateLimiting: process.env.ENABLE_RATE_LIMITING !== 'false',
        enableSecurityHeaders: process.env.ENABLE_SECURITY_HEADERS !== 'false',
        enableCors: process.env.ENABLE_CORS !== 'false',
      },
    };
  }

  validateSecrets() {
    const errors = [];

    // Validate required production secrets
    if (this.env === 'production') {
      if (!this.secrets.auth.jwtSecret) {
        errors.push('JWT_SECRET is required in production');
      }

      if (!this.secrets.database.url) {
        errors.push('DATABASE_URL is required in production');
      }

      if (this.secrets.auth.jwtSecret && this.secrets.auth.jwtSecret.length < 32) {
        errors.push('JWT_SECRET must be at least 32 characters in production');
      }
    }

    // Validate JWT secret in all environments except test
    if (this.env !== 'test' && !this.secrets.auth.jwtSecret) {
      errors.push('JWT_SECRET is required');
    }

    // Validate database URL for all environments except test
    if (this.env !== 'test' && !this.secrets.database.url) {
