    const weakSecrets = [
      'secret', 'password', '123456', 'admin', 'token',
      'test', 'development', 'changeme', 'default'
    ];

    if (jwtSecret && weakSecrets.some(weak => jwtSecret.toLowerCase().includes(weak))) {
      console.warn('WARNING: JWT_SECRET appears to be weak or default');
    }

    // Log secret info (masked)
    console.log('Secrets loaded:', {
      database: this.getSecret('DATABASE_URL') ? '[SET]' : '[MISSING]',
      jwt: this.getSecret('JWT_SECRET') ? this.maskSecret(this.getSecret('JWT_SECRET')) : '[MISSING]',
      stripe: this.getSecret('STRIPE_SECRET_KEY') ? '[SET]' : '[MISSING]',
      environment: env,
    });
  }

  // Rotate secrets (for future implementation)
  async rotateSecret(key) {
    if (!this.secrets.has(key)) {
      throw new Error(`Secret ${key} not found`);
    }

    const newValue = crypto.randomBytes(32).toString('hex');
    this.setSecret(key, newValue);

    // Here you would update the secret in your secrets manager
    console.log(`Rotated secret: ${key} (old value removed from memory)`);

    return newValue;
  }
}

// Singleton instance with lazy initialization
const secretsManager = new SecretsManager();

// Initialize on first access
let initializationPromise = null;

async function getSecretsManager() {
  if (!initializationPromise) {
    initializationPromise = secretsManager.initialize();
  }
  await initializationPromise;
  return secretsManager;
}

module.exports = {
  SecretsManager,
  getSecretsManager,
  getSecret: async (key, defaultValue) => {
    const manager = await getSecretsManager();
    return manager.getSecret(key, defaultValue);
  },
};

