#!/usr/bin/env node
// Deployment validation script
// Run before deploying to production

const crypto = require('crypto');

function validateSecrets() {
  console.log('🔒 Validating production secrets...\n');

  const errors = [];
  const warnings = [];

  // Check for required variables
  const required = ['NODE_ENV', 'JWT_SECRET', 'DATABASE_URL'];
  required.forEach(key => {
    if (!process.env[key]) {
      errors.push(`❌ Missing required variable: ${key}`);
    }
  });

  // Validate NODE_ENV
  if (process.env.NODE_ENV !== 'production') {
    errors.push('❌ NODE_ENV must be "production" in production');
  }

  // Validate JWT_SECRET strength
  const jwtSecret = process.env.JWT_SECRET;
  if (jwtSecret) {
    if (jwtSecret.length < 32) {
      errors.push('❌ JWT_SECRET must be at least 32 characters');
    }

    // Check for weak/common secrets
    const weakPatterns = ['secret', 'password', '123456', 'test', 'development'];
    if (weakPatterns.some(pattern => jwtSecret.toLowerCase().includes(pattern))) {
      warnings.push('⚠️  JWT_SECRET appears to be weak or contain common words');
    }
  }

  // Validate DATABASE_URL format
  const dbUrl = process.env.DATABASE_URL;
  if (dbUrl) {
    if (!dbUrl.startsWith('postgres://') && !dbUrl.startsWith('postgresql://')) {
      warnings.push('⚠️  DATABASE_URL should use postgres:// or postgresql:// protocol');
    }

    if (process.env.NODE_ENV === 'production' && !dbUrl.includes('ssl=true')) {
      warnings.push('⚠️  Production database should use SSL (add ?ssl=true to DATABASE_URL)');
    }
  }

  // Check for development secrets in production
  if (process.env.NODE_ENV === 'production') {
    const devIndicators = [
      'localhost', '127.0.0.1', 'test', 'development',
      'sk-test-', 'pk_test_', 'mock', 'example'
    ];

    devIndicators.forEach(indicator => {
      Object.entries(process.env).forEach(([key, value]) => {
        if (value && value.toLowerCase().includes(indicator)) {
          warnings.push(`⚠️  ${key} appears to contain development value: ${value.substring(0, 20)}...`);
        }
      });
    });
  }

  // Output results
  console.log('Validation Results:');
  console.log('='.repeat(50));

  if (errors.length === 0) {
    console.log('✅ All required checks passed');
  } else {
    console.log(`❌ ${errors.length} errors found:`);
    errors.forEach(error => console.log(`  ${error}`));
  }

  if (warnings.length > 0) {
    console.log(`\n⚠️  ${warnings.length} warnings:`);
    warnings.forEach(warning => console.log(`  ${warning}`));
  }

  console.log('\nEnvironment Summary:');
  console.log('-'.repeat(50));
  console.log(`NODE_ENV: ${process.env.NODE_ENV || 'not set'}`);
  console.log(`JWT_SECRET: ${jwtSecret ? 'Set (' + jwtSecret.length + ' chars)' : 'Not set'}`);
  console.log(`DATABASE_URL: ${dbUrl ? 'Set' : 'Not set'}`);
  console.log(`PORT: ${process.env.PORT || '3000 (default)'}`);

  return errors.length === 0;
}

if (require.main === module) {
  const isValid = validateSecrets();
  process.exit(isValid ? 0 : 1);
}

module.exports = { validateSecrets };

