const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');

const app = express();

// 1. Security Headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      objectSrc: ["'none'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      fontSrc: ["'self'"],
      connectSrc: ["'self'"],
      frameSrc: ["'none'"],
      baseUri: ["'self'"],
      formAction: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// 3. CORS Configuration
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// 4. Request Logging
app.use(morgan('combined', {
  skip: (req, res) => req.path === '/health'
}));

// 5. Body Parsing with Limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateInput = (req, res, next) => {
  // Basic sanitization for all inputs
  Object.keys(req.query).forEach(key => {
    if (typeof req.query[key] === 'string') {
      req.query[key] = req.query[key].replace(/[<>]/g, '');
    }
  });

  Object.keys(req.params).forEach(key => {
    if (typeof req.params[key] === 'string') {
      req.params[key] = req.params[key].replace(/[<>]/g, '');
    }
  });

  next();
};

app.use(validateInput);

// Secure Health Endpoint
app.get('/health', (req, res) => {
  // Minimal information for health checks
  res.set('Cache-Control', 'no-store');
  res.json({ 
    status: 'ok',
    // Remove timestamp or use epoch to reduce information disclosure
    uptime: process.uptime()
  });
});

// Secure Users Endpoint with Authentication
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const token = authHeader.substring(7);
  // In production, verify JWT token here
  // For now, this is a placeholder
  if (token !== process.env.API_TOKEN) {
    return res.status(403).json({ error: 'Invalid authentication token' });
  }

  next();
};

// Add authorization middleware
const authorize = (requiredRole) => {
  return (req, res, next) => {
    // Extract user role from JWT token (in production)
    // This is a simplified example
    const userRole = req.headers['x-user-role'] || 'user';

    if (userRole !== requiredRole) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

