/**
 * Secure Secrets Management Module
 * 
 * This module provides secure secrets management with:
 * - Environment-based configuration
 * - Secrets validation
 * - AWS Secrets Manager integration (production)
 * - Local .env files (development)
 * - Secret rotation support
 */

const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.isProduction = process.env.NODE_ENV === 'production';
    this.secretsLoaded = false;

    // Initialize AWS Secrets Manager for production
    if (this.isProduction) {
      this.awsSecretsManager = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });
    }
  }

  /**
   * Initialize secrets from appropriate source
   */
  async initialize() {
    if (this.isProduction) {
      await this.loadFromAWSSecretsManager();
    } else {
      await this.loadFromEnvironment();
    }

    this.secretsLoaded = true;
    console.log(`Secrets loaded from ${this.isProduction ? 'AWS Secrets Manager' : 'environment variables'}`);
  }

  /**
   * Load secrets from AWS Secrets Manager (production)
   */
  async loadFromAWSSecretsManager() {
    try {
      // Load different secret types from AWS
      const [appSecrets, databaseSecrets, apiSecrets] = await Promise.all([
        this.getSecretFromAWS('app-secrets'),
        this.getSecretFromAWS('database-secrets'),
        this.getSecretFromAWS('api-secrets')
      ]);

      // Merge all secrets
      this.secrets = {
        ...appSecrets,
        ...databaseSecrets,
        ...apiSecrets
      };

      // Also set them in process.env for compatibility
      Object.keys(this.secrets).forEach(key => {
        process.env[key] = this.secrets[key];
      });
    } catch (error) {
      throw new Error(`Failed to load secrets from AWS Secrets Manager: ${error.message}`);
    }
  }

  /**
   * Get a secret from AWS Secrets Manager
   */
  async getSecretFromAWS(secretName) {
    try {
      const data = await this.awsSecretsManager.getSecretValue({
        SecretId: secretName
      }).promise();

      if ('SecretString' in data) {
        return JSON.parse(data.SecretString);
      } else {
        const buff = Buffer.from(data.SecretBinary, 'base64');
        return JSON.parse(buff.toString('ascii'));
      }
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        throw new Error(`Secret ${secretName} not found in AWS Secrets Manager`);
      }
      throw error;
    }
  }

  /**
   * Load secrets from environment variables (development)
   */
  async loadFromEnvironment() {
    // Load dotenv for development
    if (process.env.NODE_ENV !== 'production') {
      require('dotenv').config();
    }

    // Load all required secrets from process.env
    const requiredSecrets = [
      'API_TOKEN',
      'SESSION_SECRET',
      'JWT_SECRET',
      'PORT',
      'NODE_ENV'
    ];

    // Optional secrets
    const optionalSecrets = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'RATE_LIMIT_WINDOW_MS',
      'RATE_LIMIT_MAX_REQUESTS',
      'ALLOWED_ORIGINS'
    ];

    // Load all secrets
    [...requiredSecrets, ...optionalSecrets].forEach(key => {
      if (process.env[key]) {
        this.secrets[key] = process.env[key];
      }
    });
  }

  /**
   * Get a secret value
   */
  get(key) {
    if (!this.secretsLoaded) {
      throw new Error('Secrets not initialized. Call initialize() first.');
    }

    const value = this.secrets[key];
    if (value === undefined) {
      throw new Error(`Secret ${key} not found`);
    }

    return value;
  }

  /**
   * Get all secrets (use with caution)
   */
  getAll() {
    return { ...this.secrets };
  }

  /**
   * Rotate a secret (production only)
   */
  async rotateSecret(secretName, newSecretValue) {
    if (!this.isProduction) {
      throw new Error('Secret rotation only supported in production');
    }

    try {
      // Update in AWS Secrets Manager
      await this.awsSecretsManager.updateSecret({
        SecretId: secretName,
        SecretString: JSON.stringify(newSecretValue)
      }).promise();

      // Update local cache
      this.secrets = {
        ...this.secrets,
        ...newSecretValue
      };

      console.log(`Secret ${secretName} rotated successfully`);
      return true;
    } catch (error) {
      console.error(`Failed to rotate secret ${secretName}:`, error);
      return false;
    }
  }

  /**
   * Validate API token
   */
  validateApiToken(token) {
    const validTokens = this.get('API_TOKEN').split(',');
    return validTokens.includes(token);
  }

  /**
   * Get database configuration
   */
  getDatabaseConfig() {
    return {
      url: this.get('DATABASE_URL'),
      ssl: this.isProduction,
      pool: {
        max: 20,
        min: 0,
        idle: 10000
      }
    };
  }

  /**
   * Get JWT configuration
   */
  getJWTConfig() {
    return {
      secret: this.get('JWT_SECRET'),
      expiresIn: '24h',
      algorithm: 'HS256'
    };
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

/**
 * Validate that all required secrets are present
 */
function validateRequiredSecrets() {
  const required = [
    'API_TOKEN',
    'SESSION_SECRET',
    'JWT_SECRET',
    'NODE_ENV'
  ];

  const missing = required.filter(key => !secretsManager.get(key));

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }

  // Validate secret strength in production
  if (process.env.NODE_ENV === 'production') {
    const sessionSecret = secretsManager.get('SESSION_SECRET');
    const jwtSecret = secretsManager.get('JWT_SECRET');

    if (sessionSecret.length < 32) {
      throw new Error('SESSION_SECRET must be at least 32 characters long in production');
    }

    if (jwtSecret.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters long in production');
    }
  }
}

module.exports = secretsManager;
module.exports.validateRequiredSecrets = validateRequiredSecrets;

