/**
 * Local Secrets Configuration for Development
 * 
 * This is a local secrets configuration that can be used during development
 * instead of relying solely on .env files. It provides a structured approach
 * to secrets management.
 */

const crypto = require('crypto');

// Generate secure random secrets for development
function generateSecureSecret(length = 32) {
  return crypto.randomBytes(length).toString('hex');
}

// Default development configuration
const developmentSecrets = {
  // Server Configuration
  PORT: 3000,
  NODE_ENV: 'development',

  // Security Configuration
  API_TOKEN: 'dev_api_token_' + generateSecureSecret(16),
  SESSION_SECRET: generateSecureSecret(32),
  JWT_SECRET: generateSecureSecret(32),

  // Database Configuration (if using)
  DATABASE_URL: 'postgres://dev_user:dev_password@localhost:5432/dev_db',

  // Rate Limiting
  RATE_LIMIT_WINDOW_MS: 900000, // 15 minutes
  RATE_LIMIT_MAX_REQUESTS: 100,

  // CORS Configuration
  ALLOWED_ORIGINS: 'http://localhost:3000,http://localhost:3001',

  // External Services (development only - use mock services or development keys)
  AWS_ACCESS_KEY_ID: 'AKIA-DEV1234567890',
  AWS_SECRET_ACCESS_KEY: 'dev_aws_secret_key_' + generateSecureSecret(24),
  STRIPE_SECRET_KEY: 'sk-test-' + generateSecureSecret(24),

  // Logging
  LOG_LEVEL: 'debug'
};

/**
 * Development Secrets Manager
 * This is a simplified version for local development that doesn't require AWS
 */
class LocalSecretsManager {
  constructor() {
    this.secrets = { ...developmentSecrets };
    this.overrideFromEnvironment();
  }

  /**
   * Override with environment variables if present
   */
  overrideFromEnvironment() {
    Object.keys(this.secrets).forEach(key => {
      if (process.env[key]) {
        this.secrets[key] = process.env[key];
      }
    });
  }

  /**
   * Get a secret value
   */
  get(key) {
    const value = this.secrets[key];
    if (value === undefined) {
      throw new Error(`Secret ${key} not found in local development configuration`);
    }
    return value;
  }

  /**
   * Validate API token
   */
  validateApiToken(token) {
    const validTokens = this.get('API_TOKEN').split(',');
    return validTokens.includes(token);
  }

  /**
   * Check if running in production mode
   */
  get isProduction() {
    return this.get('NODE_ENV') === 'production';
  }
}

// Export singleton instance
const localSecretsManager = new LocalSecretsManager();

/**
 * Validate development secrets
 */
function validateDevelopmentSecrets() {
  const required = ['API_TOKEN', 'SESSION_SECRET', 'JWT_SECRET', 'NODE_ENV'];

  required.forEach(key => {
    const value = localSecretsManager.get(key);
    if (!value) {
      throw new Error(`Missing required secret for development: ${key}`);
    }
  });

  console.log('Development secrets initialized successfully');
  console.log('API Token (first 16 chars):', localSecretsManager.get('API_TOKEN').substring(0, 16) + '...');
  console.log('Environment:', localSecretsManager.get('NODE_ENV'));
}

module.exports = localSecretsManager;
module.exports.validateDevelopmentSecrets = validateDevelopmentSecrets;

