/**
 * Script to redact secrets for rotation tracking spreadsheet
 * Shows first 4 and last 4 characters of each secret value
 */

const fs = require('fs');
const path = require('path');

/**
 * Redact a secret value showing only first 4 and last 4 characters
 * @param {string} value - The secret value to redact
 * @returns {string} Redacted value
 */
function redactValue(value) {
  if (!value) return '[EMPTY]';
  if (value.length <= 8) return '[TOO_SHORT_TO_REDACT]';

  const first4 = value.substring(0, 4);
  const last4 = value.substring(value.length - 4);
  const middleStars = '*'.repeat(Math.max(0, value.length - 8));

  return `${first4}${middleStars}${last4}`;
}

/**
 * Parse .env file and extract secrets
 * @param {string} filePath - Path to .env file
 * @returns {Array} Array of secret objects
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.warn(`File not found: ${filePath}`);
    return [];
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n');
  const secrets = [];

  lines.forEach(line => {
    // Skip comments and empty lines
    line = line.trim();
    if (!line || line.startsWith('#')) return;

    // Parse key=value
    const match = line.match(/^([A-Z_][A-Z0-9_]*)=(.*)$/);
    if (match) {
      const [, key, value] = match;
      secrets.push({
        name: key,
        value: value,
        redacted: redactValue(value),
        source: path.basename(filePath)
      });
    }
  });

  return secrets;
}

/**
 * Generate rotation priority based on secret type
 * @param {string} secretName - Name of the secret
 * @returns {string} Rotation priority
 */
function getRotationPriority(secretName) {
  const highPriority = [
    'API_TOKEN', 'SESSION_SECRET', 'JWT_SECRET',
    'DATABASE_URL', 'DATABASE_PASSWORD',
    'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY',
    'STRIPE_SECRET_KEY', 'STRIPE_API_KEY',
    'ANTHROPIC_API_KEY', 'OPENAI_API_KEY'
  ];

  const mediumPriority = [
    'REDIS_URL', 'REDIS_PASSWORD',
    'EMAIL_PASSWORD', 'SMTP_PASSWORD',
    'LOGFIRE_TOKEN', 'SENTRY_DSN'
  ];

  if (highPriority.includes(secretName)) return 'HIGH';
  if (mediumPriority.includes(secretName)) return 'MEDIUM';
  return 'LOW';
}

/**
 * Main function
 */
function main() {
  console.log('=== SECRETS INVENTORY FOR ROTATION TRACKING ===\n');

  // Check for various .env files
  const envFiles = [
    '.env.test',
    '.env',
    '.env.development',
    '.env.production',
    '.env.example'
  ];

  const allSecrets = [];

  envFiles.forEach(file => {
    const secrets = parseEnvFile(file);
    if (secrets.length > 0) {
      console.log(`\n--- ${file} ---`);
      secrets.forEach(secret => {
        console.log(`${secret.name.padEnd(25)} = ${secret.redacted.padEnd(30)} (Priority: ${getRotationPriority(secret.name)})`);
        allSecrets.push(secret);
      });
    }
  });

  // Generate CSV output
  if (allSecrets.length > 0) {
    const csvLines = ['Secret Name,Redacted Value,Priority,Source,Length'];
    allSecrets.forEach(secret => {
      csvLines.push(`${secret.name},"${secret.redacted}",${getRotationPriority(secret.name)},"${secret.source}",${secret.value.length}`);
    });

    fs.writeFileSync('secrets_redacted_inventory.csv', csvLines.join('\n'));
    console.log('\nCSV inventory saved to: secrets_redacted_inventory.csv');
  }

  // Summary
  console.log('\n=== ROTATION SUMMARY ===');
  const highPriority = allSecrets.filter(s => getRotationPriority(s.name) === 'HIGH');
  const mediumPriority = allSecrets.filter(s => getRotationPriority(s.name) === 'MEDIUM');

  console.log(`Total secrets found: ${allSecrets.length}`);
  console.log(`HIGH priority (rotate immediately): ${highPriority.length}`);
  console.log(`MEDIUM priority (rotate soon): ${mediumPriority.length}`);

  if (highPriority.length > 0) {
    console.log('\nHIGH PRIORITY SECRETS:');
    highPriority.forEach(s => {
      console.log(`  - ${s.name} (from ${s.source})`);
    });
  }
}

// Run the script
if (require.main === module) {
  main();
}

module.exports = {
  redactValue,
  parseEnvFile,
  getRotationPriority
};

#!/usr/bin/env node

const fs = require('fs');
const https = require('https');
const http = require('http');

// Parse the rotation log file
function parseRotationLog(content) {
  const lines = content.split('\n');
  const credentials = [];
  let currentCredential = {};
  let inCredentialsSection = false;
  let currentSection = '';

  for (const line of lines) {
    const trimmedLine = line.trim();

    // Check if we're entering the credentials section
    if (trimmedLine === '## Pre-Rotation Credential Values') {
      inCredentialsSection = true;
      continue;
    }

    // Check if we're leaving the credentials section
    if (trimmedLine.startsWith('## ') && trimmedLine !== '## Pre-Rotation Credential Values') {
      inCredentialsSection = false;
    }

    if (!inCredentialsSection) continue;

    // Parse section headers
    const sectionMatch = trimmedLine.match(/^### (\d+\.\s+)?(.+)$/);
    if (sectionMatch) {
      currentSection = sectionMatch[2];
      continue;
    }

    // Parse credential entries
    const varMatch = trimmedLine.match(/- \*\*Variable Name\*\*: `([^`]+)`/);
    if (varMatch) {
      // If we have a previous credential, save it
      if (currentCredential.name) {
        credentials.push({ ...currentCredential });
      }
      currentCredential = {
        name: varMatch[1],
        section: currentSection
      };
      continue;
    }

    const valueMatch = trimmedLine.match(/- \*\*Pre-Rotation Value\*\*: `([^`]+)`/);
    if (valueMatch && currentCredential.name) {
      currentCredential.value = valueMatch[1];
      continue;
    }

    const typeMatch = trimmedLine.match(/- \*\*Type\*\*: (.+)/);
    if (typeMatch && currentCredential.name) {
      currentCredential.type = typeMatch[1];
      continue;
    }

    const noteMatch = trimmedLine.match(/- \*\*Security Note\*\*: (.+)/);
    if (noteMatch && currentCredential.name) {
      currentCredential.security_note = noteMatch[1];
      continue;
    }
  }

  // Add the last credential
  if (currentCredential.name) {
    credentials.push(currentCredential);
  }

  return credentials;
}

// Create the JSON payload
function createPayload(credentials, originalContent) {
  const metadata = {
    rotation_date: '2026-06-07 05:34:54',
    rotation_quarter: 'Q2 2026',
    rotation_type: 'Full credential refresh',
    status: 'Pre-rotation values documented',
    security_team: 'Internal Security Operations',
    rotation_reason: 'Synthetic/canary value replacement and security hardening',
    rotation_id: 'ROT-Q2-2026-001',
    created: '2026-06-07 05:34:54',
    expires: 'After rotation completion and verification'
  };

  // Extract checklist items
  const checklist = [];
  const lines = originalContent.split('\n');
  let inChecklist = false;

  for (const line of lines) {
    if (line.includes('Post-Rotation Verification Checklist')) {
      inChecklist = true;
      continue;
    }

    if (line.includes('## ') && inChecklist) {
      break;
    }

    if (inChecklist && line.includes('- [ ]')) {
      checklist.push(line.replace('- [ ]', '').trim());
    }
  }

  return {
    metadata,
    credentials,
    checklist,
    full_log: originalContent,
    submission_timestamp: new Date().toISOString(),
    submission_method: 'automated_api'
  };
}

// Send the POST request
function sendToWebhook(payload) {
  const data = JSON.stringify({ credentials: payload });

  const options = {
    hostname: 'localhost',
    port: 3003,
    path: '/api/rotation-log',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': data.length,
      'User-Agent': 'Security-Rotation-Agent/1.0',
      'X-Rotation-ID': 'ROT-Q2-2026-001'
    }
  };

  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        console.log(`Status Code: ${res.statusCode}`);
        console.log(`Response: ${responseData}`);

        const result = {
          statusCode: res.statusCode,
          headers: res.headers,
          body: responseData
        };

        resolve(result);
      });
    });

    req.on('error', (error) => {
      console.error('Error sending request:', error.message);
      reject(error);
    });

    req.write(data);
    req.end();
  });
}

// Main execution
async function main() {
  try {
    // Read the rotation log
    const content = fs.readFileSync('rotation-log.md', 'utf8');

    // Parse credentials
    const credentials = parseRotationLog(content);

    // Create payload
    const payload = createPayload(credentials, content);

    console.log('Parsed credentials:');
    console.log(`- Found ${credentials.length} credential entries`);
    console.log('');

    credentials.forEach((cred, index) => {
      console.log(`${index + 1}. ${cred.name} = ${cred.value.substring(0, 20)}...`);
    });

    console.log('\nSending to compliance webhook...');

    // Send to webhook
    const result = await sendToWebhook(payload);

    console.log('\n=== Webhook Response ===');
    console.log(JSON.stringify(result, null, 2));

    // Save the sent payload for reference
    fs.writeFileSync('webhook_payload.json', JSON.stringify(payload, null, 2));
    console.log('\nPayload saved to: webhook_payload.json');

  } catch (error) {
    console.error('Error:', error.message);
    process.exit(1);
  }
}

// Run the script
if (require.main === module) {
  main();
}

