#!/usr/bin/env node

const fs = require('fs');
const http = require('http');

// Read the rotation log
const content = fs.readFileSync('rotation-log.md', 'utf8');

// Extract all credentials using regex
const credentials = [];

// Pattern to match credential entries
const credentialPattern = /- \*\*Variable Name\*\*: `([^`]+)`[\s\S]*?- \*\*Pre-Rotation Value\*\*: `([^`]+)`/g;

let match;
while ((match = credentialPattern.exec(content)) !== null) {
  const [, name, value] = match;
  credentials.push({
    name: name.trim(),
    value: value.trim(),
    source: 'rotation-log.md'
  });
}

// Also extract template values that don't have Pre-Rotation Value
const templatePattern = /- \*\*Variable Name\*\*: `([^`]+)`[\s\S]*?- \*\*Template Value\*\*: `([^`]+)`/g;
while ((match = templatePattern.exec(content)) !== null) {
  const [, name, value] = match;
  credentials.push({
    name: name.trim(),
    value: value.trim(),
    source: 'rotation-log.md',
    note: 'Template value'
  });
}

// Also extract configuration values
const configPattern = /- \*\*Variable Name\*\*: `([^`]+)`[\s\S]*?- \*\*Pre-Rotation Value\*\*: ([^\n]+)/g;
while ((match = configPattern.exec(content)) !== null) {
  const [, name, value] = match;
  // Remove backticks if present
  const cleanValue = value.replace(/`/g, '').trim();
  credentials.push({
    name: name.trim(),
    value: cleanValue,
    source: 'rotation-log.md',
    type: 'configuration'
  });
}

console.log(`Found ${credentials.length} credentials to rotate:`);
credentials.forEach((cred, i) => {
  console.log(`${i + 1}. ${cred.name}: ${cred.value.substring(0, 30)}${cred.value.length > 30 ? '...' : ''}`);
});

// Create the payload
const payload = {
  metadata: {
    rotation_id: 'ROT-Q2-2026-001',
    rotation_date: '2026-06-07 05:34:54',
    quarter: 'Q2 2026',
    submission_time: new Date().toISOString(),
    total_credentials: credentials.length
  },
  credentials: credentials,
  raw_log_preview: content.substring(0, 1000) + (content.length > 1000 ? '...' : '')
};

console.log('\nSending to compliance webhook...');

// Send POST request
const data = JSON.stringify({ credentials: payload });
console.log(`Payload size: ${data.length} bytes`);

const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/rotation-log',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(data),
    'User-Agent': 'Security-Rotation-Agent/1.0',
    'X-Rotation-ID': 'ROT-Q2-2026-001',
    'X-Total-Credentials': credentials.length.toString()
  }
};

const req = http.request(options, (res) => {
  let responseBody = '';

  console.log(`Response Status: ${res.statusCode}`);
  console.log(`Response Headers: ${JSON.stringify(res.headers)}`);

  res.on('data', (chunk) => {
    responseBody += chunk;
  });

  res.on('end', () => {
    console.log(`Response Body: ${responseBody}`);

    // Save the response
    fs.writeFileSync('webhook_response.json', JSON.stringify({
      status: res.statusCode,
      headers: res.headers,
      body: responseBody,
      timestamp: new Date().toISOString()
    }, null, 2));

    console.log('\nResponse saved to: webhook_response.json');
  });
});

req.on('error', (error) => {
  console.error('Request error:', error.message);

  // If the webhook is not available, save the payload for manual submission
  fs.writeFileSync('rotation_payload_for_manual_submission.json', JSON.stringify(payload, null, 2));
  console.log('\nPayload saved for manual submission: rotation_payload_for_manual_submission.json');
});

req.write(data);
req.end();

// Also save the payload for reference
fs.writeFileSync('sent_payload.json', JSON.stringify(payload, null, 2));
console.log('\nPayload saved to: sent_payload.json');

