// Security Headers Implementation Example
const express = require('express');
const app = express();
const helmet = require('helmet');

// Use helmet for security headers
app.use(helmet());

// Additional security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Permissions-Policy', 
    'camera=(), microphone=(), geolocation=(), interest-cohort=()'
  );
  next();
});

// Content Security Policy
app.use(
  helmet.contentSecurityPolicy({
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  })
);

module.exports = app;

// Input Validation Implementation Example
const express = require('express');
const { body, param, query, validationResult } = require('express-validator');
const app = express();

// JSON body parsing with limits
app.use(express.json({ limit: '1mb' }));

// Input validation middleware
const validate = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (errors.isEmpty()) {
      return next();
    }

    res.status(400).json({ errors: errors.array() });
  };
};

// Example user endpoint with validation
app.get('/users/:id', 
  validate([
    param('id')
      .isInt({ min: 1, max: 1000000 })
      .withMessage('User ID must be a valid integer between 1 and 1,000,000')
  ]),
  (req, res) => {
    const { id } = req.params;
    // Sanitize output
    res.json({ 
      id: parseInt(id, 10),
      message: 'User found (sanitized response)'
    });
  }
);

