// utils/secrets.js
const fs = require('fs').promises;
const path = require('path');

async function loadSecrets() {
  const secrets = {};

  // Priority 1: Environment variables
  Object.assign(secrets, process.env);

  // Priority 2: Docker secrets (if running in container)
  if (process.env.DOCKER_SECRETS_PATH) {
    try {
      const secretFiles = await fs.readdir(process.env.DOCKER_SECRETS_PATH);
      for (const file of secretFiles) {
        const secretPath = path.join(process.env.DOCKER_SECRETS_PATH, file);
        const content = await fs.readFile(secretPath, 'utf8');
        secrets[file] = content.trim();
      }
    } catch (error) {
      console.warn('Could not load Docker secrets:', error.message);
    }
  }

  // Priority 3: Mounted secret volumes
  const mountedSecrets = ['/run/secrets', '/etc/secrets'];
  for (const mountPath of mountedSecrets) {
    try {
      const files = await fs.readdir(mountPath);
      for (const file of files) {
        const secretPath = path.join(mountPath, file);
        const content = await fs.readFile(secretPath, 'utf8');
        secrets[file] = content.trim();
      }
    } catch (error) {
      // Ignore - path doesn't exist
    }
  }

  return secrets;
}

module.exports = { loadSecrets };
