/**
 * Secure Express Application
 * Updated to address OWASP Top 10 vulnerabilities
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const Joi = require('joi');
require('dotenv').config();

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Security headers (A05: Security Misconfiguration)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"]
    }
  }
}));

// 2. CORS configuration (A07: Cross-Site Scripting prevention)
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// 3. Rate limiting (A04: Insecure Design)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false
});
app.use(limiter);

// 4. Request logging
app.use(morgan('combined'));

// 5. Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 6. Disable X-Powered-By header
app.disable('x-powered-by');

// ========== INPUT VALIDATION MIDDLEWARE ==========

// Validation for user ID parameter
const validateUserId = (req, res, next) => {
  const schema = Joi.object({
    id: Joi.number().integer().min(1).required()
  });

  const { error } = schema.validate({ id: req.params.id });
  if (error) {
    return res.status(400).json({ 
      error: 'Invalid user ID',
      details: error.details[0].message 
    });
  }

  next();
};

// ========== AUTHENTICATION MIDDLEWARE ==========

const authenticateApiKey = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];
  const validApiKey = process.env.API_KEY;

  if (!apiKey) {
    return res.status(401).json({ 
      error: 'Authentication required',
      message: 'API key is missing in x-api-key header'
    });
  }

  // Use constant-time comparison to prevent timing attacks
  const crypto = require('crypto');
  const providedKeyHash = crypto.createHash('sha256').update(apiKey).digest('hex');
  const validKeyHash = crypto.createHash('sha256').update(validApiKey || '').digest('hex');

  if (!crypto.timingSafeEqual(
    Buffer.from(providedKeyHash),
    Buffer.from(validKeyHash)
  )) {
    return res.status(403).json({ 
      error: 'Access denied',
      message: 'Invalid API key'
    });
  }

  next();
};

// ========== SANITIZATION MIDDLEWARE ==========

// Basic XSS protection
const sanitizeInput = (req, res, next) => {
  // Sanitize query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].replace(/[<>]/g, '');
      }
    });
  }

  // Sanitize body parameters
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      if (typeof req.body[key] === 'string') {
        req.body[key] = req.body[key].replace(/[<>]/g, '');
      }
    });
  }

  next();
};

// ========== ROUTES WITH SECURITY ==========

// Public health endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Public users endpoint (with input sanitization)
app.get('/users', sanitizeInput, (req, res) => {
  // Simulated database response with additional protection
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      // Never include sensitive data in public endpoints
      created_at: new Date().toISOString()
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
      created_at: new Date().toISOString()
    },
  ];

  // Filter any null/undefined values
  const safeUsers = users.map(user => ({
    id: user.id,
    name: user.name || '',
    email: user.email || ''
  }));

  res.json(safeUsers);
});

// Protected admin endpoint
app.get('/admin/users', authenticateApiKey, (req, res) => {
  // This would fetch from database in real implementation
  res.json({
    message: 'Admin access granted',
    data: [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' }
    ]
  });
});

// User details with parameter validation
app.get('/users/:id', validateUserId, sanitizeInput, (req, res) => {
  const userId = parseInt(req.params.id, 10);

  // In real app, use parameterized database queries
  // Example: pool.query('SELECT * FROM users WHERE id = $1', [userId])

  res.json({
    id: userId,
    name: 'User ' + userId,
    email: `user${userId}@example.com`
  });
});

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Application Error:', {
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't expose error details in production
  const errorResponse = {
    error: 'Internal Server Error',
    timestamp: new Date().toISOString()
  };

  if (process.env.NODE_ENV === 'development') {
    errorResponse.details = err.message;
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// ========== SERVER INITIALIZATION ==========

const port = process.env.PORT || 3000;
const server = app.listen(port, () => {
  console.log(`Secure server running on port ${port}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`CORS allowed origins: ${corsOptions.origin.join(', ')}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

/**
 * Security Test Suite
 * Run with: node security_test.js
 */

const https = require('https');
