/**
 * Production-Grade Secrets Manager
 * Implements security best practices for secrets management
 * 
 * Features:
 * 1. Multi-source secrets loading (env vars, AWS Secrets Manager, Vault, .env files)
 * 2. Validation and type checking
 * 3. Secret rotation support
 * 4. Local development safety
 * 5. Audit logging
 * 6. Mock secrets for testing
 */

const crypto = require('crypto');

class SecretsManager {
  constructor(options = {}) {
    this.options = {
      // Order of precedence for secret sources
      sources: ['environment', 'file', 'aws', 'vault'],
      // Required secrets - will throw if missing in production
      requiredSecrets: [
        'API_KEY',
        'DATABASE_URL',
        'JWT_SECRET',
        'PORT'
      ],
      // Optional secrets with defaults
      optionalSecrets: {
        NODE_ENV: 'development',
        LOG_LEVEL: 'info',
        ALLOWED_ORIGINS: 'http://localhost:3000'
      },
      // Validation patterns
      validations: {
        API_KEY: /^[a-zA-Z0-9_-]{32,}$/,
        DATABASE_URL: /^postgres:\/\/.+/,
        JWT_SECRET: /^[a-zA-Z0-9]{32,}$/,
        PORT: /^[0-9]{2,5}$/
      },
      // Local development safety
      allowLocalEnvFiles: process.env.NODE_ENV !== 'production',
      // Cache TTL in milliseconds
      cacheTTL: 300000, // 5 minutes
      ...options
    };

    this.secrets = new Map();
    this.cacheTimestamp = 0;
    this.initialized = false;
  }

  /**
   * Initialize and load all secrets
   */
  async initialize() {
    if (this.initialized && Date.now() - this.cacheTimestamp < this.options.cacheTTL) {
      return this.secrets;
    }

    console.log('[SecretsManager] Loading secrets from sources:', this.options.sources);

    // Load from each source in order of precedence
    for (const source of this.options.sources) {
      try {
        await this.loadFromSource(source);
      } catch (error) {
        console.warn(`[SecretsManager] Failed to load from ${source}:`, error.message);
      }
    }

    // Apply defaults for optional secrets
    this.applyDefaults();

    // Validate required secrets in production
    if (process.env.NODE_ENV === 'production') {
      this.validateRequiredSecrets();
    }

    this.cacheTimestamp = Date.now();
    this.initialized = true;

    // Log loaded secrets (without values in production)
    this.logSecretsSummary();

    return this.secrets;
  }

  /**
   * Load secrets from a specific source
   */
  async loadFromSource(source) {
    switch (source) {
      case 'environment':
        return this.loadFromEnvironment();
      case 'file':
        return this.loadFromFile();
      case 'aws':
        return await this.loadFromAwsSecretsManager();
      case 'vault':
        return await this.loadFromVault();
      case 'test':
        return this.loadTestSecrets();
      default:
        throw new Error(`Unknown secret source: ${source}`);
    }
  }

  /**
   * Load from environment variables
   */
  loadFromEnvironment() {
    console.log('[SecretsManager] Loading from environment variables');

    for (const [key, value] of Object.entries(process.env)) {
      if (value && key.startsWith('APP_') || this.options.requiredSecrets.includes(key)) {
        this.secrets.set(key, value);
      }
    }
  }

  /**
   * Load from .env file (only in development)
   */
  loadFromFile() {
    if (!this.options.allowLocalEnvFiles) {
      console.log('[SecretsManager] Skipping .env file in production');
      return;
    }

    try {
      // Use dotenv only in development
      const path = require('path');
      const envPath = path.resolve(process.cwd(), '.env');

      if (require('fs').existsSync(envPath)) {
        console.log('[SecretsManager] Loading from .env file');
        const result = require('dotenv').config({ path: envPath });

        if (result.error) {
          throw result.error;
        }

        // Add loaded secrets
        for (const [key, value] of Object.entries(result.parsed || {})) {
          this.secrets.set(key, value);
        }
      }
    } catch (error) {
      console.warn('[SecretsManager] Error loading .env file:', error.message);
    }
  }

  /**
   * Load from AWS Secrets Manager
   */
  async loadFromAwsSecretsManager() {
    if (process.env.NODE_ENV !== 'production') {
      console.log('[SecretsManager] Skipping AWS Secrets Manager in non-production');
      return;
    }

    try {
      const { SecretsManager } = require('@aws-sdk/client-secrets-manager');
      const client = new SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });

      const secretName = process.env.AWS_SECRET_NAME || 'app/production';
      console.log(`[SecretsManager] Loading from AWS Secrets Manager: ${secretName}`);

      const response = await client.getSecretValue({ SecretId: secretName });

      if (response.SecretString) {
        const secrets = JSON.parse(response.SecretString);
        for (const [key, value] of Object.entries(secrets)) {
          this.secrets.set(key, value);
        }
      }
    } catch (error) {
      console.error('[SecretsManager] AWS Secrets Manager error:', error.message);
      throw error;
    }
  }

  /**
   * Load from HashiCorp Vault
   */
  async loadFromVault() {
    if (process.env.NODE_ENV !== 'production') {
      console.log('[SecretsManager] Skipping Vault in non-production');
      return;
    }

    try {
      // This would require the vault npm package
      // const vault = require('node-vault');
      // const client = vault({ apiVersion: 'v1', endpoint: process.env.VAULT_ADDR });

      // const response = await client.read('secret/data/app');
      // const secrets = response.data.data;

      // for (const [key, value] of Object.entries(secrets)) {
      //   this.secrets.set(key, value);
      // }

      console.log('[SecretsManager] Vault integration would go here');
    } catch (error) {
      console.error('[SecretsManager] Vault error:', error.message);
      throw error;
    }
  }

  /**
   * Load mock secrets for testing
   */
  loadTestSecrets() {
    if (process.env.NODE_ENV !== 'test') {
      return;
    }

    console.log('[SecretsManager] Loading test secrets');

    const testSecrets = {
      API_KEY: 'test-api-key-1234567890',
      DATABASE_URL: 'postgres://test:test@localhost:5432/test',
      JWT_SECRET: 'test-jwt-secret-1234567890',
      PORT: '3001',
      NODE_ENV: 'test'
    };

    for (const [key, value] of Object.entries(testSecrets)) {
      this.secrets.set(key, value);
    }
  }

  /**
   * Apply defaults for optional secrets
   */
  applyDefaults() {
    for (const [key, defaultValue] of Object.entries(this.options.optionalSecrets)) {
      if (!this.secrets.has(key) || !this.secrets.get(key)) {
        this.secrets.set(key, defaultValue);
      }
    }
  }

  /**
   * Validate that all required secrets are present
   */
  validateRequiredSecrets() {
    const missingSecrets = [];
    const invalidSecrets = [];

    for (const secretName of this.options.requiredSecrets) {
      const value = this.secrets.get(secretName);

      if (!value) {
        missingSecrets.push(secretName);
        continue;
      }

      // Validate format if validation pattern exists
      const validationPattern = this.options.validations[secretName];
      if (validationPattern && !validationPattern.test(value)) {
        invalidSecrets.push({ secretName, value: this.maskSecret(value) });
      }
    }

    if (missingSecrets.length > 0) {
      throw new Error(`Missing required secrets: ${missingSecrets.join(', ')}`);
    }

    if (invalidSecrets.length > 0) {
      console.warn('[SecretsManager] Some secrets have invalid format:', invalidSecrets);
    }
  }

  /**
   * Get a secret by name
   */
  get(secretName) {
    if (!this.initialized) {
      throw new Error('SecretsManager not initialized. Call initialize() first.');
    }

    const value = this.secrets.get(secretName);

    if (!value && this.options.requiredSecrets.includes(secretName)) {
      throw new Error(`Required secret not found: ${secretName}`);
    }

    return value;
  }

  /**
   * Get all secrets (for debugging, masked in production)
   */
  getAll() {
    const result = {};

    for (const [key, value] of this.secrets.entries()) {
      if (process.env.NODE_ENV === 'production') {
        result[key] = this.maskSecret(value);
      } else {
        result[key] = value;
      }
    }

    return result;
  }

  /**
   * Mask a secret for logging
   */
  maskSecret(value) {
    if (!value || typeof value !== 'string') {
      return '***';
    }

    if (value.length <= 8) {
      return '*'.repeat(value.length);
    }

    return value.substring(0, 4) + '*'.repeat(6) + value.substring(value.length - 4);
  }

  /**
   * Log summary of loaded secrets
   */
  logSecretsSummary() {
    const summary = {};
    const maskedSecrets = {};

    for (const [key, value] of this.secrets.entries()) {
      summary[key] = value ? '✓' : '✗';
      maskedSecrets[key] = this.maskSecret(value);
    }

    console.log('[SecretsManager] Secrets loaded:', summary);

    if (process.env.NODE_ENV !== 'production') {
      console.log('[SecretsManager] Secret values (development only):', maskedSecrets);
    }
  }

  /**
   * Rotate a secret (in a real implementation, this would update the source)
   */
  async rotateSecret(secretName, newValue) {
    if (process.env.NODE_ENV !== 'production') {
      console.log(`[SecretsManager] Would rotate ${secretName} in production`);
      this.secrets.set(secretName, newValue);
      return true;
    }

    // In production, we would:
    // 1. Update in AWS Secrets Manager/Vault
    // 2. Update local cache
    // 3. Log the rotation

    console.log(`[SecretsManager] Secret rotation not implemented for ${secretName}`);
    return false;
  }

  /**
   * Audit secret access
   */
  auditAccess(secretName, operation, userId = 'system') {
    const auditLog = {
      timestamp: new Date().toISOString(),
      secretName,
      operation,
      userId,
      environment: process.env.NODE_ENV || 'development',
      maskedValue: this.maskSecret(this.secrets.get(secretName))
    };

    // In production, send to centralized logging
    if (process.env.NODE_ENV === 'production') {
      console.log('[SecretsManager Audit]', JSON.stringify(auditLog));
    }
  }
}

// Factory function for common use cases
const createSecretsManager = (environment = process.env.NODE_ENV || 'development') => {
  const configs = {
    development: {
      sources: ['environment', 'file', 'test'],
      allowLocalEnvFiles: true,
      requiredSecrets: ['API_KEY', 'PORT'],
      cacheTTL: 60000 // 1 minute for development
    },
    test: {
      sources: ['test', 'environment'],
      requiredSecrets: ['API_KEY', 'DATABASE_URL', 'PORT'],
      cacheTTL: 0 // No cache for tests
    },
    production: {
      sources: ['aws', 'vault', 'environment'],
      allowLocalEnvFiles: false,
      requiredSecrets: ['API_KEY', 'DATABASE_URL', 'JWT_SECRET', 'PORT'],
      cacheTTL: 300000 // 5 minutes
    }
  };

  const config = configs[environment] || configs.development;
  return new SecretsManager(config);
};

module.exports = {
  SecretsManager,
  createSecretsManager
};

/**
 * Production-Secure Express Application
 * Uses proper secrets management instead of direct .env loading
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const Joi = require('joi');

// Use proper secrets management
const { createSecretsManager } = require('./secrets_manager');

// Initialize secrets manager
const secretsManager = createSecretsManager(process.env.NODE_ENV);

const app = express();

// ========== ASYNC INITIALIZATION ==========

(async () => {
  try {
    // Initialize secrets before setting up the app
    await secretsManager.initialize();

    const PORT = secretsManager.get('PORT') || 3000;
    const NODE_ENV = secretsManager.get('NODE_ENV') || 'development';
    const ALLOWED_ORIGINS = secretsManager.get('ALLOWED_ORIGINS') || 'http://localhost:3000';

    // ========== SECURITY MIDDLEWARE ==========

    // 1. Security headers
    app.use(helmet({
      contentSecurityPolicy: {
        directives: {
          defaultSrc: ["'self'"],
          scriptSrc: ["'self'"],
          styleSrc: ["'self'", "'unsafe-inline'"],
          imgSrc: ["'self'", "data:", "https:"]
        }
      }
    }));

    // 2. CORS configuration
    const corsOptions = {
      origin: ALLOWED_ORIGINS.split(','),
      credentials: true,
      optionsSuccessStatus: 200
    };
    app.use(cors(corsOptions));

    // 3. Rate limiting
    const limiter = rateLimit({
      windowMs: 15 * 60 * 1000, // 15 minutes
      max: 100,
      message: 'Too many requests from this IP, please try again later.',
      standardHeaders: true,
      legacyHeaders: false
    });
    app.use(limiter);

    // 4. Request logging
    app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

    // 5. Body parsing with size limits
    app.use(express.json({ limit: '10kb' }));
    app.use(express.urlencoded({ extended: true, limit: '10kb' }));

    // 6. Disable X-Powered-By header
    app.disable('x-powered-by');

    // ========== AUTHENTICATION MIDDLEWARE ==========

    const authenticateApiKey = (req, res, next) => {
      const apiKey = req.headers['x-api-key'];
      const validApiKey = secretsManager.get('API_KEY');

      // Audit the access attempt
      secretsManager.auditAccess('API_KEY', 'access_attempt', req.ip);

      if (!apiKey) {
        return res.status(401).json({ 
          error: 'Authentication required',
          message: 'API key is missing in x-api-key header'
        });
      }

      // Constant-time comparison to prevent timing attacks
      const crypto = require('crypto');
      const providedKeyHash = crypto.createHash('sha256').update(apiKey).digest('hex');
      const validKeyHash = crypto.createHash('sha256').update(validApiKey || '').digest('hex');

      if (!crypto.timingSafeEqual(
        Buffer.from(providedKeyHash),
        Buffer.from(validKeyHash)
      )) {
        // Log failed authentication attempt
        console.warn(`Failed API key attempt from ${req.ip}`);
        return res.status(403).json({ 
          error: 'Access denied',
          message: 'Invalid API key'
        });
      }

      next();
    };

    // ========== HEALTH CHECK ENDPOINT ==========

    app.get('/health', (req, res) => {
      // Health check includes secrets manager status
      res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        secrets: secretsManager.initialized ? 'loaded' : 'uninitialized',
        environment: NODE_ENV
      });
    });

    // ========== SECRETS MANAGEMENT ENDPOINTS ==========
    // Note: These endpoints should be heavily protected in production

    app.get('/admin/secrets/status', authenticateApiKey, (req, res) => {
      // Only return metadata, never actual secret values
      const secrets = secretsManager.getAll();
      const status = {
        initialized: secretsManager.initialized,
        lastUpdated: secretsManager.cacheTimestamp,
        totalSecrets: Object.keys(secrets).length,
        environment: NODE_ENV
      };

      res.json(status);
    });

    // ========== PUBLIC ENDPOINTS ==========

    app.get('/users', (req, res) => {
      // Static data endpoint - no secrets exposure
      const users = [
        { 
          id: 1, 
          name: 'Alice', 
          email: 'alice@example.com',
          created_at: new Date().toISOString()
        },
        { 
          id: 2, 
          name: 'Bob', 
          email: 'bob@example.com',
          created_at: new Date().toISOString()
        },
      ];

      const safeUsers = users.map(user => ({
        id: user.id,
        name: user.name || '',
        email: user.email || ''
      }));

      res.json(safeUsers);
    });

    // ========== PROTECTED ENDPOINTS ==========

    app.get('/admin/users', authenticateApiKey, (req, res) => {
      // This would fetch from database using secrets from secrets manager
      const databaseUrl = secretsManager.get('DATABASE_URL');

      res.json({
        message: 'Admin access granted',
        environment: NODE_ENV,
        database: databaseUrl ? 'configured' : 'not configured',
        data: [
          { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
          { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' }
        ]
      });
    });

    // ========== SECRETS REFRESH ENDPOINT ==========

    app.post('/admin/secrets/refresh', authenticateApiKey, async (req, res) => {
      try {
        await secretsManager.initialize();
        res.json({ 
          status: 'success',
          message: 'Secrets refreshed successfully',
          timestamp: new Date().toISOString()
        });
      } catch (error) {
        console.error('Failed to refresh secrets:', error);
        res.status(500).json({ 
          status: 'error',
          message: 'Failed to refresh secrets',
          error: NODE_ENV === 'development' ? error.message : undefined
        });
      }
    });

    // ========== ERROR HANDLING ==========

    // 404 handler
    app.use((req, res) => {
      res.status(404).json({
        error: 'Not Found',
        message: `Cannot ${req.method} ${req.path}`,
        timestamp: new Date().toISOString()
      });
    });

    // Global error handler
    app.use((err, req, res, next) => {
      console.error('Application Error:', {
        timestamp: new Date().toISOString(),
        error: err.message,
        stack: NODE_ENV === 'development' ? err.stack : undefined,
        path: req.path,
        method: req.method,
        ip: req.ip
      });

      // Don't expose error details in production
      const errorResponse = {
        error: 'Internal Server Error',
        timestamp: new Date().toISOString()
      };

      if (NODE_ENV === 'development') {
        errorResponse.details = err.message;
      }

      res.status(err.status || 500).json(errorResponse);
    });

    // ========== START SERVER ==========

    const server = app.listen(PORT, () => {
      console.log(`
=========================================
🚀 Production-Secure Server Started
=========================================
Port: ${PORT}
Environment: ${NODE_ENV}
Secrets Manager: ${secretsManager.initialized ? '✓ Initialized' : '✗ Failed'}
CORS Origins: ${ALLOWED_ORIGINS}
Node Version: ${process.version}
=========================================
      `);
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      console.log('SIGTERM signal received: closing HTTP server');
      server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
      });
    });

    process.on('SIGINT', () => {
      console.log('SIGINT signal received: closing HTTP server');
      server.close(() => {
        console.log('HTTP server closed');
        process.exit(0);
      });
    });

  } catch (error) {
    console.error('Failed to initialize application:', error);
    process.exit(1);
  }
})();

module.exports = app;

