/**
 * Credentials Rotation Helper
 * Provides redacted views and generation utilities for credential rotation
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

class CredentialRotator {
  constructor() {
    this.envFile = '.env.test';
    this.rotationLog = 'credentials_rotation_log.json';
  }

  /**
   * Read and redact credentials from .env.test
   */
  readAndRedact() {
    console.log('🔐 CREDENTIALS REDACTION REPORT');
    console.log('=' .repeat(60));

    try {
      if (!fs.existsSync(this.envFile)) {
        console.log(`❌ File ${this.envFile} not found`);
        return null;
      }

      const content = fs.readFileSync(this.envFile, 'utf8');
      const lines = content.split('\n');

      const credentials = [];

      lines.forEach(line => {
        line = line.trim();

        // Skip comments and empty lines
        if (!line || line.startsWith('#')) {
          return;
        }

        // Parse key=value
        const eqIndex = line.indexOf('=');
        if (eqIndex === -1) {
          return;
        }

        const key = line.substring(0, eqIndex).trim();
        const value = line.substring(eqIndex + 1).trim();

        if (value) {
          const redacted = this.redactValue(value);
          credentials.push({ key, value, redacted });
        }
      });

      return credentials;

    } catch (error) {
      console.error('Error reading credentials:', error.message);
      return null;
    }
  }

  /**
   * Redact a credential value (first 4 + last 4 chars)
   */
  redactValue(value) {
    if (!value || value.length <= 8) {
      return '*'.repeat(value.length || 0);
    }

    const firstPart = value.substring(0, 4);
    const lastPart = value.substring(value.length - 4);

    return `${firstPart}...${lastPart}`;
  }

  /**
   * Display redacted credentials in table format
   */
  displayRedactedTable(credentials) {
    if (!credentials || credentials.length === 0) {
      console.log('No credentials found to redact');
      return;
    }

    console.log('\n📋 REDACTED CREDENTIALS FOR ROTATION TRACKING:');
    console.log('-' .repeat(80));
    console.log('Variable Name'.padEnd(25) + ' | ' + 'Redacted Value'.padEnd(30) + ' | Length');
    console.log('-' .repeat(80));

    credentials.forEach(cred => {
      console.log(
        cred.key.padEnd(25) + ' | ' +
        cred.redacted.padEnd(30) + ' | ' +
        cred.value.length.toString().padStart(3)
      );
    });

    console.log('-' .repeat(80));
  }

  /**
   * Display CSV format for spreadsheet import
   */
  displayCSVFormat(credentials) {
    if (!credentials || credentials.length === 0) {
      return;
    }

    console.log('\n📊 CSV FORMAT FOR SPREADSHEET IMPORT:');
    console.log('Variable Name,Redacted Value,Type,Priority,Owner,Rotation Due Date,Status,Notes');

    // Priority mapping based on key names
    const getPriority = (key) => {
      if (key.includes('STRIPE') || key.includes('DATABASE') || key.includes('AWS')) {
        return 'HIGH';
      }
      return 'MEDIUM';
    };

    // Type mapping
    const getType = (key) => {
      if (key.includes('URL')) return 'Connection String';
      if (key.includes('KEY')) return 'API Key';
      if (key.includes('TOKEN')) return 'Access Token';
      if (key.includes('SECRET')) return 'Secret Key';
      if (key.includes('ID')) return 'Access Key ID';
      return 'Credential';
    };

    // Owner mapping
    const getOwner = (key) => {
      if (key.includes('DATABASE')) return 'Database Team';
      if (key.includes('AWS')) return 'DevOps Team';
      if (key.includes('STRIPE')) return 'Finance Team';
