# Security Review for app.js

## Critical Findings

### 1. **Sensitive Information Exposure**
**File**: `.env.test`
**Issue**: Hardcoded production-like credentials in version control
**Risk Level**: CRITICAL
**Impact**: Full system compromise if leaked
**Recommendation**:
1. Remove `.env.test` from git tracking
2. Use environment variables with proper secret management
3. Implement secrets rotation

**Code Fix**:
```javascript
// Remove hardcoded credentials and use proper environment management
// .gitignore should include:
.env*
*.env
!*.env.example

// Create .env.example (without real secrets)
DATABASE_URL=your_database_url_here
AWS_ACCESS_KEY_ID=your_aws_key_id_here
AWS_SECRET_ACCESS_KEY=your_aws_secret_here
ANTHROPIC_API_KEY=your_api_key_here
STRIPE_SECRET_KEY=your_stripe_key_here
LOGFIRE_TOKEN=your_logfire_token_here

// In app.js, use process.env
const dbUrl = process.env.DATABASE_URL;
```

### 2. **SQL/NoSQL Injection Vulnerabilities**
**Issue**: Potential injection if database queries are added without parameterization
**Risk Level**: CRITICAL
**Impact**: Data breach, data loss, or full system compromise

**Code Fix**:
```javascript
// BAD - Vulnerable to SQL injection
// app.get('/user/:id', (req, res) => {
//   const query = `SELECT * FROM users WHERE id = ${req.params.id}`;
// });

// GOOD - Use parameterized queries
app.get('/user/:id', (req, res) => {
  const userId = req.params.id;
  // Using pg library example
  pool.query('SELECT * FROM users WHERE id = $1', [userId], (error, results) => {
    if (error) {
      res.status(500).json({ error: 'Database error' });
      return;
    }
    res.json(results.rows);
  });
});
```

### 3. **Cross-Site Scripting (XSS)**
**Issue**: No output encoding for user-controllable data
**Risk Level**: HIGH

**Code Fix**:
```javascript
// Install required packages
// npm install helmet

const helmet = require('helmet');
app.use(helmet());

// Set Content Security Policy
app.use(
  helmet.contentSecurityPolicy({
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  })
);

// Sanitize user input
const { body, validationResult } = require('express-validator');

app.post('/user',
  [
    body('name').trim().escape(),
    body('email').isEmail().normalizeEmail(),
    body('bio').trim().escape()
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Process sanitized input
  }
);
```

### 4. **Missing Authentication and Authorization**
**Issue**: No authentication for accessing user data
**Risk Level**: HIGH

**Code Fix**:
```javascript
// Install required packages
// npm install jsonwebtoken bcryptjs

const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.status(401).json({ error: 'Access token required' });

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

// Authorization middleware
const authorizeRoles = (...roles) => {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

// Protect routes
app.get('/users', authenticateToken, authorizeRoles('admin'), (req, res) => {
  // Only admin can access all users
  res.json(users);
});
```

### 5. **Missing Input Validation**
**Issue**: No validation of user input
**Risk Level**: HIGH

**Code Fix**:
```javascript
const { body, param, query, validationResult } = require('express-validator');

// Comprehensive input validation
app.get('/user/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer')
      .toInt(),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt()
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Process validated input
  }
);
```

### 6. **Security Misconfiguration**
**Issue**: Default Express settings with security flaws
**Risk Level**: MEDIUM

**Code Fix**:
```javascript
const express = require('express');
const app = express();

// Security headers
const helmet = require('helmet');
app.use(helmet());

// Disable X-Powered-By header
app.disable('x-powered-by');

// Prevent parameter pollution
app.set('query parser', 'extended');

// Request size limiting
const expressLimit = require('express-rate-limit');
const limiter = expressLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Enable CORS with proper configuration
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Body parsing with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

### 7. **Insufficient Logging and Monitoring**
**Issue**: No audit logging for security events
**Risk Level**: MEDIUM

**Code Fix**:
```javascript
const winston = require('winston');
const morgan = require('morgan');

// Configure logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// HTTP request logging with security events
const securityLogger = morgan('combined', {
  skip: (req, res) => res.statusCode < 400,
  stream: {
    write: (message) => logger.info(message.trim())
  }
});
app.use(securityLogger);

// Log security events
app.use((req, res, next) => {
  // Log authentication attempts
  if (req.path.includes('/login') || req.path.includes('/auth')) {
    logger.info('Authentication attempt', {
      ip: req.ip,
      userAgent: req.headers['user-agent'],
      timestamp: new Date().toISOString()
    });
  }
  next();
});
```

### 8. **Dependency Vulnerabilities**
**Issue**: No dependency security checking
**Risk Level**: MEDIUM

**Recommendation**:
1. Use `npm audit` regularly
2. Implement CI/CD security scanning
3. Use dependabot or similar tools

**Package.json additions**:
```json
{
  "scripts": {
    "audit": "npm audit",
    "audit:fix": "npm audit fix",
    "security-check": "npx snyk test",
    "depcheck": "npx depcheck"
  },
  "devDependencies": {
    "snyk": "^latest"
  }
}
```

### 9. **Missing HTTPS/SSL**
**Issue**: No SSL/TLS enforcement
**Risk Level**: MEDIUM

**Code Fix**:
```javascript
// For production, always use HTTPS
if (process.env.NODE_ENV === 'production') {
  const https = require('https');
  const fs = require('fs');

  const options = {
    key: fs.readFileSync('/path/to/private/key.pem'),
    cert: fs.readFileSync('/path/to/certificate.pem')
  };

  https.createServer(options, app).listen(443, () => {
    console.log('HTTPS server running on port 443');
  });

  // Redirect HTTP to HTTPS
  const http = require('http');
  http.createServer((req, res) => {
    res.writeHead(301, { Location: `https://${req.headers.host}${req.url}` });
    res.end();
  }).listen(80);
} else {
  app.listen(3000, () => {
    console.log('Development server running on port 3000');
  });
}
```

## Immediate Action Items

### CRITICAL Priority (Fix immediately):
1. Remove `.env.test` from git and add to `.gitignore`
2. Implement proper environment variable management
3. Add input validation for all endpoints
4. Implement authentication middleware

### HIGH Priority (Fix within 1 week):
1. Add security headers with helmet.js
2. Implement parameterized queries for database operations
3. Add rate limiting
4. Set up error handling that doesn't leak stack traces

### MEDIUM Priority (Fix within 1 month):
1. Implement comprehensive logging
2. Add security monitoring
3. Set up dependency vulnerability scanning
4. Configure HTTPS for production

## Additional Recommendations

### 1. **OWASP ASVS Compliance**
Implement controls from OWASP Application Security Verification Standard:
- V1: Architecture, Design and Threat Modeling
- V2: Authentication
- V3: Session Management
- V4: Access Control
- V5: Validation, Sanitization and Encoding
- V6: Stored Cryptography
- V7: Error Handling and Logging
