```javascript
// config/secrets.js - Professional secret management
const { SecretsManager } = require('@aws-sdk/client-secrets-manager');
const crypto = require('crypto');

class SecretManager {
  constructor() {
    this.cache = new Map();
    this.initialized = false;
  }

  async initialize() {
    if (this.initialized) return;

    // For AWS Secrets Manager (Production)
    if (process.env.NODE_ENV === 'production' && process.env.AWS_REGION) {
      this.client = new SecretsManager({ region: process.env.AWS_REGION });
      this.mode = 'aws';
    } 
    // For Azure Key Vault
    else if (process.env.AZURE_KEY_VAULT_NAME) {
      this.mode = 'azure';
    }
    // For local development with encryption
    else {
      this.mode = 'encrypted-file';
    }

    this.initialized = true;
  }

  async getSecret(secretName) {
    await this.initialize();

    // Check cache first
    if (this.cache.has(secretName)) {
      return this.cache.get(secretName);
    }

    let secretValue;

    switch (this.mode) {
      case 'aws':
        const response = await this.client.getSecretValue({ SecretId: secretName });
        secretValue = response.SecretString;
        break;

      case 'encrypted-file':
        // Local encrypted file storage
        const fs = require('fs');
        const encrypted = fs.readFileSync(`./secrets/${secretName}.enc`, 'utf8');
        const decipher = crypto.createDecipheriv(
          'aes-256-gcm',
          Buffer.from(process.env.ENCRYPTION_KEY, 'hex'),
          Buffer.from(process.env.ENCRYPTION_IV, 'hex')
        );
        secretValue = decipher.update(encrypted, 'hex', 'utf8');
        break;

      default:
        // Fallback to environment variables (development only)
        secretValue = process.env[secretName];
    }

    // Cache the secret
    this.cache.set(secretName, secretValue);
    return secretValue;
  }

  // Rotate secrets periodically
  startRotation() {
    setInterval(() => {
      this.cache.clear();
    }, 3600000); // Clear cache every hour
  }
}

module.exports = new SecretManager();
```

