// config/secrets-manager.js
const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

class SecretsManagerService {
  constructor() {
    this.client = new SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
  }

  async getSecret(secretName) {
    try {
      const response = await this.client.getSecretValue({
        SecretId: secretName
      });

      if ('SecretString' in response) {
        return JSON.parse(response.SecretString);
      }

      return Buffer.from(response.SecretBinary, 'base64').toString('ascii');
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw error;
    }
  }

  async loadAppSecrets() {
    const secrets = await this.getSecret('app/production/secrets');

    // Set environment variables from secrets
    Object.entries(secrets).forEach(([key, value]) => {
      process.env[key] = value;
    });

    return secrets;
  }
}

module.exports = SecretsManagerService;
```

