      }

    } else if (this.env === 'staging') {
      // Staging: Use different secret store
      const vault = new VaultService();
      await vault.loadSecrets();

    } else if (this.env === 'test') {
      // Test: Use mock/fake secrets ONLY
      this.loadMockSecrets();

    } else {
      // Development: Use .env file with validation
      this.validateDevSecrets();
    }

    this.postLoadValidation();
  }

  loadMockSecrets() {
