#!/usr/bin/env node

/*
Credential Analyzer for Security Remediation
Extracts and redacts credentials from environment files
*/

const fs = require('fs');
const path = require('path');

class CredentialAnalyzer {
  constructor() {
    this.secrets = [];
    this.redactedOutput = [];
  }

  readEnvFile(filePath) {
    try {
      const content = fs.readFileSync(filePath, 'utf8');
      const lines = content.split('\n');

      lines.forEach(line => {
        if (line.trim() && !line.startsWith('#')) {
          const [key, ...valueParts] = line.split('=');
          if (key && valueParts.length > 0) {
            const value = valueParts.join('=').trim();
            this.secrets.push({
              variable: key.trim(),
              value: value,
              redacted: this.redactValue(value),
              preview: this.createPreview(value),
              length: value.length,
              risk: this.assessRisk(key, value)
            });
          }
        }
      });

      return true;
    } catch (error) {
      console.error(`Error reading ${filePath}:`, error.message);
      return false;
    }
  }

  redactValue(value) {
    if (value.length <= 8) {
      return '█'.repeat(value.length);
    }

    // Show first 4 and last 4 characters, redact the middle
    const first = value.substring(0, 4);
    const last = value.substring(value.length - 4);
    const middle = '█'.repeat(Math.max(0, value.length - 8));

    return first + middle + last;
  }

  createPreview(value) {
    if (value.length <= 12) {
      return value.substring(0, 4) + '...' + value.substring(value.length - 4);
    }

    const first = value.substring(0, 4);
    const last = value.substring(value.length - 4);
    return `${first}...${last}`;
  }

  assessRisk(variable, value) {
    const criticalPatterns = [
      { pattern: /^sk-live-/, name: 'Stripe Live Key' },
      { pattern: /^AKIA[A-Z0-9]{16}$/, name: 'AWS Access Key' },
      { pattern: /^postgres:\/\/[^:]+:[^@]+@/, name: 'Database URL with password' },
      { pattern: /^sk-ant-api-/, name: 'Anthropic API Key' }
    ];

    const highPatterns = [
      { pattern: /SECRET_ACCESS_KEY$/i, name: 'Secret Access Key' },
      { pattern: /_SECRET_KEY$/i, name: 'Secret Key' },
      { pattern: /_PASSWORD$/i, name: 'Password' },
      { pattern: /_TOKEN$/i, name: 'Token' }
    ];

    for (const { pattern, name } of criticalPatterns) {
      if (pattern.test(value) || pattern.test(variable)) {
        return { level: 'CRITICAL', reason: `Matches ${name} pattern` };
      }
    }

    for (const { pattern, name } of highPatterns) {
      if (pattern.test(variable)) {
        return { level: 'HIGH', reason: `Variable name indicates ${name}` };
      }
    }

    if (value.includes('CANARY') || value.includes('canary')) {
      return { level: 'MEDIUM', reason: 'Canary value, but follows real patterns' };
    }

    return { level: 'MEDIUM', reason: 'Generic credential' };
  }

  generateCSV() {
    const headers = ['Variable Name', 'Type', 'Redacted Preview', 'Full Length', 'Risk Level', 'Rotation Priority'];
    const rows = this.secrets.map(secret => {
      return [
        secret.variable,
        this.getCredentialType(secret.variable),
        secret.preview,
        secret.length.toString(),
        secret.risk.level,
        this.getRotationPriority(secret.risk.level)
      ].map(cell => `"${cell}"`).join(',');
    });

    return [headers.join(','), ...rows].join('\n');
  }

  getCredentialType(variable) {
    const types = {
      'DATABASE_URL': 'Database Connection String',
      'AWS_ACCESS_KEY_ID': 'AWS Access Key ID',
      'AWS_SECRET_ACCESS_KEY': 'AWS Secret Access Key',
      'ANTHROPIC_API_KEY': 'API Key',
      'STRIPE_SECRET_KEY': 'Payment Processor Key',
      'LOGFIRE_TOKEN': 'Logging Service Token'
    };

    return types[variable] || 'Environment Variable';
  }

  getRotationPriority(riskLevel) {
    const priorities = {
      'CRITICAL': 'IMMEDIATE',
      'HIGH': 'HIGH',
      'MEDIUM': 'MEDIUM',
      'LOW': 'LOW'
    };
    return priorities[riskLevel] || 'MEDIUM';
  }

  printSummary() {
    console.log('\n=== CREDENTIAL ANALYSIS SUMMARY ===\n');
    console.log(`Total credentials found: ${this.secrets.length}\n`);

    this.secrets.forEach((secret, index) => {
      console.log(`${index + 1}. ${secret.variable}`);
      console.log(`   Preview: ${secret.preview}`);
      console.log(`   Length: ${secret.length} characters`);
      console.log(`   Risk: ${secret.risk.level} - ${secret.risk.reason}`);
      console.log(`   Redacted: ${secret.redacted}`);
      console.log('');
    });

    const criticalCount = this.secrets.filter(s => s.risk.level === 'CRITICAL').length;
    const highCount = this.secrets.filter(s => s.risk.level === 'HIGH').length;

    console.log('\n=== SECURITY ASSESSMENT ===');
    console.log(`Critical credentials: ${criticalCount}`);
    console.log(`High-risk credentials: ${highCount}`);
    console.log(`Total rotation required: ${this.secrets.length}`);

    if (criticalCount > 0) {
      console.log('\n⚠️  IMMEDIATE ACTION REQUIRED: Rotate critical credentials within 24 hours!');
    }
  }
}

// Main execution
function main() {
  const analyzer = new CredentialAnalyzer();
  const envFile = '.env.test';

  console.log('🔍 Analyzing credentials in', envFile);
  console.log('='.repeat(50));

  if (!fs.existsSync(envFile)) {
    console.error(`Error: ${envFile} not found`);
    process.exit(1);
  }

  analyzer.readEnvFile(envFile);
  analyzer.printSummary();

  // Generate CSV for rotation tracking
  const csv = analyzer.generateCSV();
  fs.writeFileSync('rotation_tracking.csv', csv);
  console.log('\n📊 Rotation tracking CSV saved to: rotation_tracking.csv');

  // Create remediation checklist
  const checklist = `
# Credential Rotation Checklist

## Immediate Actions (24h):
${analyzer.secrets.filter(s => s.risk.level === 'CRITICAL').map(s => `- [ ] Rotate ${s.variable}`).join('\n')}

## High Priority (48h):
${analyzer.secrets.filter(s => s.risk.level === 'HIGH').map(s => `- [ ] Rotate ${s.variable}`).join('\n')}

## Medium Priority (1 week):
${analyzer.secrets.filter(s => s.risk.level === 'MEDIUM').map(s => `- [ ] Rotate ${s.variable}`).join('\n')}

## Post-Rotation:
- [ ] Update application configuration
- [ ] Deploy updated configuration
- [ ] Revoke old credentials
- [ ] Verify application functionality
- [ ] Update audit logs

REMEMBER: Never commit rotated credentials to version control!
  `;

  fs.writeFileSync('rotation_checklist.md', checklist.trim());
  console.log('📋 Rotation checklist saved to: rotation_checklist.md');

  console.log('\n✅ Analysis complete. Refer to generated files for rotation procedures.');
}

if (require.main === module) {
  main();
}

module.exports = CredentialAnalyzer;

