    }

    this.initialized = true;
  }

  async loadFromAWSSecretsManager() {
    const client = new SecretsManagerClient({
      region: process.env.AWS_REGION
    });

    const requiredSecrets = [
      'database',
      'redis',
      'jwt-secret',
      'third-party-apis'
    ];

    for (const secretName of requiredSecrets) {
      try {
        const command = new GetSecretValueCommand({
          SecretId: `${process.env.APP_NAME}/${secretName}`
        });
        const response = await client.send(command);
        this.secrets[secretName] = JSON.parse(response.SecretString);
      } catch (error) {
        console.error(`Failed to load secret ${secretName}:`, error);
        throw new Error(`Missing required secret: ${secretName}`);
      }
    }
  }

  async loadFromEnvWithValidation() {
    const required = {
      DATABASE_URL: 'string',
      JWT_SECRET: 'string',
      REDIS_URL: 'string'
    };

    for (const [key, type] of Object.entries(required)) {
      if (!process.env[key]) {
        throw new Error(`Missing required environment variable: ${key}`);
      }

      // Store with type checking
      this.secrets[key.toLowerCase()] = process.env[key];
    }

    // Warn if using default values in production-like environments
    if (process.env.NODE_ENV === 'staging' || process.env.NODE_ENV === 'production') {
      console.warn('WARNING: Using environment variables instead of secrets manager');
    }
  }

  get(key) {
    if (!this.initialized) {
      throw new Error('Config not initialized. Call initialize() first.');
    }
    return this.secrets[key];
  }
}

