// Read the rotation log file
const rotationLog = fs.readFileSync('./rotation-log.md', 'utf8');

// Parse the rotation log to extract structured data
function parseRotationLog(content) {
  const lines = content.split('\n');
  const credentials = [];
  let currentCredential = null;
  let inCredentialsSection = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();

    // Detect start of credentials section
    if (line === '## Pre-Rotation Credential Values') {
      inCredentialsSection = true;
      continue;
    }

    // Detect end of credentials section
    if (line.startsWith('## ') && line !== '## Pre-Rotation Credential Values' && inCredentialsSection) {
      inCredentialsSection = false;
      if (currentCredential) {
        credentials.push(currentCredential);
        currentCredential = null;
      }
      break;
    }

    if (inCredentialsSection) {
      // Check if this is a credential header (like "### DATABASE_URL")
      if (line.startsWith('### ')) {
        if (currentCredential) {
          credentials.push(currentCredential);
        }
        const name = line.substring(4).trim();
        currentCredential = {
          name: name,
          type: '',
          status: 'Pre-Rotation',
          fullValue: '',
          notes: ''
        };
      }

      // Parse credential details
      if (currentCredential) {
        if (line.startsWith('**Type**:')) {
          currentCredential.type = line.split('**:')[1].trim();
        } else if (line.startsWith('**Full Value**:')) {
          // Extract the value between backticks
          const match = line.match(/`([^`]+)`/);
          if (match) {
            currentCredential.fullValue = match[1];
          }
        } else if (line.startsWith('**Security Notes**:')) {
          currentCredential.notes = line.split('**:')[1].trim();
        } else if (line.includes('**Status**:')) {
          const statusMatch = line.match(/\*\*Status\*\*: ([^\*]+)/);
          if (statusMatch) {
            currentCredential.status = statusMatch[1].trim();
          }
        }
      }
    }
  }

  // Add the last credential if exists
  if (currentCredential) {
    credentials.push(currentCredential);
  }

  // Fallback: If parsing failed, provide the full content
  if (credentials.length === 0) {
    return {
      rawContent: content,
      credentials: [
        {
          name: "FULL_LOG",
          type: "Complete Rotation Log",
          status: "Pre-Rotation",
          fullValue: content.substring(0, 500) + "... [truncated]",
          notes: "Parsing failed, sending full log content"
        }
      ]
    };
  }

  return credentials;
}

