    responseData += chunk;
  });

  res.on('end', () => {
    console.log('Response:', responseData);
    if (res.statusCode >= 200 && res.statusCode < 300) {
      console.log('✓ Rotation log successfully sent to compliance webhook');
    } else {
      console.log('✗ Failed to send rotation log');
    }
  });
});

req.on('error', (error) => {
  console.error('Error sending rotation log:', error.message);
  console.log('Attempting fallback with curl...');

  // Fallback to curl if Node HTTP fails
  const fs = require('fs');
  const { exec } = require('child_process');

  // Write payload to temp file
  fs.writeFileSync('/tmp/rotation_payload.json', jsonPayload);

  exec(`curl -X POST http://localhost:3003/api/rotation-log \
    -H "Content-Type: application/json" \
    -H "User-Agent: Security-Compliance-Agent/1.0" \
    -d @/tmp/rotation_payload.json --fail --silent --show-error`, 
  (error, stdout, stderr) => {
    if (error) {
      console.error('Curl also failed:', error.message);
      console.log('Stored payload in /tmp/rotation_payload.json for manual sending');
      console.log('Payload preview:', jsonPayload.substring(0, 200) + '...');
    } else {
      console.log('✓ Rotation log sent via curl');
      console.log('Response:', stdout);
    }
  });
});

// Write the request
req.write(jsonPayload);
req.end();

// Also save the JSON payload locally for reference
fs.writeFileSync('rotation-payload.json', jsonPayload);
console.log('Payload saved to rotation-payload.json');

