// Secure Express application
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const app = express();

// Load environment variables
require('dotenv').config();

// Basic security validation
if (!process.env.NODE_ENV) {
  console.warn('Warning: NODE_ENV not set, defaulting to development');
  process.env.NODE_ENV = 'development';
}

// Security middleware
app.use(helmet());

// CORS configuration
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? (process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : [])
    : '*',
  credentials: true,
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: process.env.NODE_ENV === 'production' ? 100 : 1000, // Different limits for dev/prod
  message: { error: 'Too many requests from this IP, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing middleware with size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// Simple authentication middleware (can be expanded)
const requireAuth = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];

  if (!apiKey) {
    return res.status(401).json({ 
      error: 'Authentication required',
      message: 'Please provide an API key in the x-api-key header'
    });
  }

  // In production, validate against database or secure storage
  if (apiKey !== process.env.API_KEY && process.env.NODE_ENV === 'production') {
    return res.status(403).json({ error: 'Invalid API key' });
  }

  next();
};

// Public endpoints
app.get('/health', (req, res) => {
  // Minimal health check response
  res.json({ 
    status: 'ok',
    environment: process.env.NODE_ENV,
    timestamp: new Date().toISOString().split('T')[0] // Date only
  });
});

// Protected endpoints
app.get('/users', requireAuth, (req, res) => {
  // Return sanitized user data
  const users = [
    { id: 1, name: 'Alice', role: 'user' },
    { id: 2, name: 'Bob', role: 'user' },
  ];

  // Additional filtering based on permissions could be added here
  res.json(users);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err.message);

  const statusCode = err.statusCode || 500;
  const errorResponse = {
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' 
      ? 'An unexpected error occurred' 
      : err.message,
    status: statusCode
  };

  // Don't expose stack traces in production
  if (process.env.NODE_ENV !== 'production') {
    errorResponse.stack = err.stack;
  }

  res.status(statusCode).json(errorResponse);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running in ${process.env.NODE_ENV} mode on port ${PORT}`);
});

module.exports = app;

