### **2. Implement Proper Secrets Management**

**Option A: Environment Variables with Validation**
```javascript
// secrets.js - Centralized secrets management
'use strict';

class SecretsManager {
  constructor() {
    this.validateRequiredSecrets();
  }

  validateRequiredSecrets() {
    const required = ['DREDD_API_KEY'];
    const missing = required.filter(key => !process.env[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
    }
  }

  get dreddApiKey() {
    return process.env.DREDD_API_KEY;
  }

  get isProduction() {
    return process.env.NODE_ENV === 'production';
  }

  // Never log full secrets
  safeLog() {
    return {
      dreddApiKeySet: !!process.env.DREDD_API_KEY,
      awsRegion: process.env.AWS_REGION,
      nodeEnv: process.env.NODE_ENV,
      // Never include actual secret values
    };
  }
}

module.exports = new SecretsManager();
```

**Option B: Use AWS Secrets Manager or Similar**
```javascript
// With AWS Secrets Manager (recommended for production)
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

async function getSecret(secretName) {
  try {
    const data = await secretsManager.getSecretValue({ SecretId: secretName }).promise();

    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    } else {
      const buff = new Buffer(data.SecretBinary, 'base64');
      return JSON.parse(buff.toString('ascii'));
    }
  } catch (err) {
    console.error(`Error retrieving secret: ${secretName}`, err);
    throw err;
  }
}

// Usage
const secrets = await getSecret('app/production/secrets');
```

### **3. Add Security Middleware to Prevent Information Disclosure**

```javascript
// security.js - Middleware to prevent secret leakage
const securityMiddleware = (req, res, next) => {
  // Remove sensitive headers
  res.removeHeader('X-Powered-By');

  // Add security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Block paths that could expose configuration
  const blockedPaths = ['/env', '/config', '/process', '/debug'];
  if (blockedPaths.includes(req.path)) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  next();
};

// Error handler that doesn't leak secrets
const errorHandler = (err, req, res, next) => {
  console.error('Application error:', err.message);

  const response = {
    error: 'Internal Server Error',
    timestamp: new Date().toISOString(),
    requestId: req.id || Math.random().toString(36).substr(2, 9)
  };

  // Never include error details or stack traces in production
  if (process.env.NODE_ENV === 'development') {
    response.message = err.message;
  }

  res.status(500).json(response);
};
```

### **4. Implement Secret Rotation and Monitoring**

```javascript
// secret-rotation.js - Auto-rotate and monitor secrets
const crypto = require('crypto');

class SecretMonitor {
  constructor() {
    this.secretHashes = new Map();
    this.rotationInterval = 24 * 60 * 60 * 1000; // 24 hours

    this.initializeMonitoring();
  }

  initializeMonitoring() {
    // Hash all current secrets for comparison
    this.hashSecrets();

    // Monitor for changes
    setInterval(() => this.checkForLeaks(), this.rotationInterval);
  }

  hashSecrets() {
    const secrets = {
      dreddApiKey: process.env.DREDD_API_KEY,
      awsRegion: process.env.AWS_REGION
    };

    Object.entries(secrets).forEach(([key, value]) => {
      if (value) {
        const hash = crypto.createHash('sha256').update(value).digest('hex');
        this.secretHashes.set(key, hash);
      }
    });
  }

  checkForLeaks() {
    // Compare current hashes with known hashes
    // Log if secrets appear to have changed unexpectedly
    console.log('Secret integrity check:', this.secretHashes);
  }
}
```

