function redactValue(value, visibleChars = 4) {
  if (!value || typeof value !== 'string') {
    return '[EMPTY OR NON-STRING]';
  }

  if (value.length <= visibleChars * 2) {
    // For short values, show partial redaction
    return '***' + value.slice(-visibleChars);
