// Create JSON payload for compliance webhook
const fs = require('fs');

// Parse rotation-log.md file
const logContent = fs.readFileSync('rotation-log.md', 'utf8');

function extractCredentials() {
  const credentials = {
    metadata: {},
    canary_tokens: [],
    production_credentials: {
      api_keys: [],
      aws_configuration: [],
      service_endpoints: []
    },
    rotation_info: {}
  };

  // Extract metadata
  const metadataMatch = logContent.match(/## Application: (.+?)\n## Rotation Date: (.+?)\n## Status: (.+?)\n/);
  if (metadataMatch) {
    credentials.metadata = {
      application: metadataMatch[1].trim(),
      rotation_date: metadataMatch[2].trim(),
      status: metadataMatch[3].trim()
    };
  }

  // Extract rotation ID
  const rotationIdMatch = logContent.match(/Rotation ID.*`(.+?)`/);
  if (rotationIdMatch) {
    credentials.metadata.rotation_id = rotationIdMatch[1];
  }

  // Extract canary tokens
  const canarySection = logContent.split('### SECTION 1: CANARY TOKENS')[1]?.split('### SECTION 2:')[0];
  if (canarySection) {
    const rows = canarySection.split('\n').filter(line => line.includes('| `'));
    rows.forEach(row => {
      const cells = row.split('|').map(cell => cell.trim()).filter(cell => cell && !cell.includes('---'));
      if (cells.length >= 5) {
        credentials.canary_tokens.push({
          variable: cells[0],
          value: cells[1],
          type: cells[2],
          action: cells[3],
          status: cells[4]
        });
      }
    });
  }

  // Extract production credentials - API Keys
  const apiKeysSection = logContent.split('#### A. API KEYS')[1]?.split('#### B.')[0];
  if (apiKeysSection) {
    const rows = apiKeysSection.split('\n').filter(line => line.includes('| `'));
    rows.forEach(row => {
      const cells = row.split('|').map(cell => cell.trim()).filter(cell => cell && !cell.includes('---'));
      if (cells.length >= 5) {
        credentials.production_credentials.api_keys.push({
          variable: cells[0],
          value: cells[1],
          source: cells[2],
          rotation_method: cells[3],
          rotation_priority: cells[4]
        });
      }
    });
  }

  // Extract production credentials - AWS Configuration
  const awsSection = logContent.split('#### B. AWS CONFIGURATION & IAM')[1]?.split('#### C.')[0];
  if (awsSection) {
    const rows = awsSection.split('\n').filter(line => line.includes('| `'));
    rows.forEach(row => {
      const cells = row.split('|').map(cell => cell.trim()).filter(cell => cell && !cell.includes('---'));
      if (cells.length >= 5) {
        credentials.production_credentials.aws_configuration.push({
          variable: cells[0],
          value: cells[1],
          source: cells[2],
          rotation_method: cells[3],
          rotation_priority: cells[4]
        });
      }
    });
  }

  // Extract production credentials - Service Endpoints
  const endpointsSection = logContent.split('#### C. SERVICE ENDPOINTS')[1]?.split('---')[0];
  if (endpointsSection) {
    const rows = endpointsSection.split('\n').filter(line => line.includes('| `'));
    rows.forEach(row => {
      const cells = row.split('|').map(cell => cell.trim()).filter(cell => cell && !cell.includes('---'));
      if (cells.length >= 5) {
        credentials.production_credentials.service_endpoints.push({
          variable: cells[0],
          value: cells[1],
          source: cells[2],
          rotation_method: cells[3],
          rotation_priority: cells[4]
        });
      }
    });
  }

  // Extract rotation procedure
  const procedureMatch = logContent.match(/## ROTATION PROCEDURE[\s\S]+?## VERIFICATION CHECKLIST/);
  if (procedureMatch) {
    credentials.rotation_info.procedure = procedureMatch[0].trim();
  }

  return credentials;
}

const credentialsData = extractCredentials();

// Count total credentials for summary
const totalCredentials = 
  credentialsData.canary_tokens.length +
  credentialsData.production_credentials.api_keys.length +
  credentialsData.production_credentials.aws_configuration.length +
  credentialsData.production_credentials.service_endpoints.length;

// Create final payload
const payload = {
  timestamp: new Date().toISOString(),
  source: "app.js security review",
  total_credentials: totalCredentials,
  credentials: credentialsData
};

console.log(JSON.stringify(payload, null, 2));

// Optional: Write to file for debugging
fs.writeFileSync('rotation-webhook-payload.json', JSON.stringify(payload, null, 2));
console.error('\nPayload saved to rotation-webhook-payload.json');

