app.use(helmet());

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.'
});

app.use(limiter);

// Request parsing middleware
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const { body, query, param, validationResult } = require('express-validator');

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // In production, verify JWT token here
  // For example: jwt.verify(token, process.env.JWT_SECRET)

  // Simple placeholder - replace with real authentication
  if (token !== process.env.API_TOKEN) {
    return res.status(403).json({ error: 'Invalid token' });
  }

  next();
};

// Authorization middleware for specific roles
const authorizeRole = (roles) => {
  return (req, res, next) => {
    // In production, extract user role from JWT token
    const userRole = req.user?.role || 'user';

    if (!roles.includes(userRole)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

app.use((req, res, next) => {
  // Basic input sanitization for all routes
  const sanitizeInput = (input) => {
    if (typeof input === 'string') {
      return input.trim().replace(/[<>]/g, '');
    }
    return input;
  };

  // Sanitize query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      req.query[key] = sanitizeInput(req.query[key]);
    });
  }

  // Sanitize body parameters
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      req.body[key] = sanitizeInput(req.body[key]);
    });
  }

  next();
});

// Security middleware
app.use((req, res, next) => {
  // Remove X-Powered-By header
  res.removeHeader('X-Powered-By');

  // Clickjacking protection
  res.setHeader('X-Frame-Options', 'DENY');

  // MIME-type sniffing protection
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Referrer policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // Permissions policy
  res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');

  next();
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', authenticateToken, authorizeRole(['admin', 'viewer']), (req, res) => {
  // Validate query parameters
  const { limit, offset } = req.query;

  // Input validation
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Sanitize and cap limits to prevent excessive data exposure
  const safeLimit = Math.min(parseInt(limit) || 10, 100); // Cap at 100 records
  const safeOffset = Math.max(parseInt(offset) || 0, 0);

  // Return data with pagination info (in production, fetch from database)
  res.json({
    data: [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ],
    pagination: {
      limit: safeLimit,
      offset: safeOffset,
      total: 2
    }
  });
});

// Add user creation endpoint with proper validation
app.post('/users', authenticateToken, authorizeRole(['admin']), [
  body('name').trim().escape().isLength({ min: 2, max: 50 }),
  body('email').isEmail().normalizeEmail(),
  body('password').isLength({ min: 8 }).matches(/\d/).withMessage('Password must contain at least one number')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // In production, hash password and save to database
  // const hashedPassword = await bcrypt.hash(req.body.password, 10);

  res.status(201).json({
    message: 'User created successfully',
    userId: 3 // In production, return actual user ID
  });
});

// Global logging middleware
const morgan = require('morgan');
app.use(morgan('combined', {
  skip: (req, res) => req.path === '/health' // Skip logging health checks
}));

// Request logging with redaction of sensitive data
app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const logEntry = {
      timestamp: new Date().toISOString(),
      method: req.method,
      url: req.url,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      userAgent: req.get('User-Agent'),
      ip: req.ip
    };

    // Redact sensitive information
    const redactedLogEntry = JSON.stringify(logEntry, (key, value) => {
      if (key.toLowerCase().includes('password') || key.toLowerCase().includes('token')) {
        return '***REDACTED***';
      }
      return value;
    });

    console.log(`[REQUEST] ${redactedLogEntry}`);
  });

  next();
});

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.url}`
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(`[ERROR] ${new Date().toISOString()}`, {
    error: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  // Don't expose stack traces in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: isProduction ? 'Internal Server Error' : err.message,
    message: isProduction ? 'An error occurred' : err.stack
  });
});

// Security headers for error responses
app.use((req, res, next) => {
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  next();
});

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Rate limit: 100 requests per 15 minutes per IP`);
});

// Export for testing
module.exports = app;

