// Security Configuration File
// Centralized security configuration for the application

module.exports = {
  // CORS Configuration
  cors: {
    enabled: process.env.ENABLE_CORS !== 'false',
    options: {
      origin: process.env.ALLOWED_ORIGINS 
        ? process.env.ALLOWED_ORIGINS.split(',') 
        : ['http://localhost:3000'],
      credentials: true,
      methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
      allowedHeaders: [
        'Content-Type',
        'Authorization',
        'X-Requested-With',
        'Accept',
        'Origin'
      ],
      exposedHeaders: ['Content-Range', 'X-Content-Range'],
      maxAge: 86400 // 24 hours
    }
  },

  // Rate Limiting Configuration
  rateLimit: {
    enabled: process.env.ENABLE_RATE_LIMITING !== 'false',
    options: {
      windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000, // 15 minutes
      max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
      standardHeaders: true,
      legacyHeaders: false,
      skipSuccessfulRequests: false,
      keyGenerator: (req) => {
        // Use IP address for rate limiting
        return req.ip || req.connection.remoteAddress;
      },
      handler: (req, res) => {
        res.status(429).json({
          error: 'Too Many Requests',
          message: 'You have exceeded the rate limit. Please try again later.',
          retryAfter: Math.ceil((parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 900000) / 1000)
        });
      }
    }
  },

  // Helmet.js Security Headers Configuration
  helmet: {
    enabled: process.env.ENABLE_SECURITY_HEADERS !== 'false',
    options: {
      contentSecurityPolicy: {
        directives: {
          defaultSrc: ["'self'"],
          styleSrc: ["'self'", "'unsafe-inline'"],
          scriptSrc: ["'self'"],
          imgSrc: ["'self'", "data:", "https:"],
          connectSrc: ["'self'"],
          fontSrc: ["'self'"],
          objectSrc: ["'none'"],
          mediaSrc: ["'self'"],
          frameSrc: ["'none'"]
        }
      },
      hsts: {
        maxAge: 31536000, // 1 year
        includeSubDomains: true,
        preload: true
      },
      frameguard: {
        action: 'deny'
      },
      referrerPolicy: {
        policy: 'strict-origin-when-cross-origin'
      },
      permissionsPolicy: {
        features: {
          camera: ["'none'"],
          microphone: ["'none'"],
          geolocation: ["'none'"]
        }
      }
    }
  },

  // Input Validation Rules
  validationRules: {
    user: {
      name: {
        minLength: 2,
        maxLength: 50,
        pattern: /^[a-zA-Z\s]+$/,
        trim: true
      },
      email: {
        minLength: 5,
        maxLength: 254,
        normalize: true
      },
      password: {
        minLength: 8,
        requireNumbers: true,
        requireUppercase: true,
        requireLowercase: true,
        requireSpecialChars: true
      }
    },
    common: {
      id: {
        pattern: /^[0-9]+$/,
        maxLength: 10
      },
      limit: {
        min: 1,
        max: 100,
        default: 10
      },
      offset: {
        min: 0,
        default: 0
      }
    }
  },

  // Authentication Configuration
  auth: {
    jwt: {
      secret: process.env.JWT_SECRET,
      expiresIn: process.env.JWT_EXPIRES_IN || '24h',
      algorithm: 'HS256'
    },
    saltRounds: 10, // For bcrypt
    tokenType: 'Bearer'
  },

  // Logging Configuration
  logging: {
    enabled: process.env.ENABLE_LOGGING !== 'false',
    level: process.env.LOG_LEVEL || 'info',
    format: process.env.LOG_FORMAT || 'combined',
    redactFields: [
      'password',
      'token',
      'authorization',
      'apiKey',
      'secret',
      'creditCard',
      'ssn',
      'phone'
    ],
    excludePaths: ['/health', '/favicon.ico']
  },

  // Session Configuration
  session: {
    enabled: process.env.ENABLE_SESSIONS === 'true',
    secret: process.env.SESSION_SECRET,
    cookie: {
      secure: process.env.NODE_ENV === 'production',
      httpOnly: true,
      sameSite: 'strict',
      maxAge: 24 * 60 * 60 * 1000 // 24 hours
    }
  },

  // Request Configuration
  request: {
    maxBodySize: '10mb',
    maxUrlSize: 2048,
    trustProxy: process.env.TRUST_PROXY || false
  },

  // Response Configuration
  response: {
    removePoweredBy: true,
    enableCSP: true,
    enableHSTS: process.env.NODE_ENV === 'production'
  },

  // Security Monitoring
  monitoring: {
    enableAuthLogging: true,
    enableRateLimitLogging: true,
    enableErrorLogging: true,
    alertThresholds: {
      authFailures: 5, // Alert after 5 failed attempts
      rateLimitExceeded: 20, // Alert after 20 rate limit hits
      serverErrors: 10 // Alert after 10 5xx errors per minute
    }
  },

  // API Security
  api: {
    version: 'v1',
    enableVersioning: true,
    requireApiKey: false, // Set to true for external APIs
    apiKeyHeader: 'X-API-Key'
  },

  // File Upload Security
  uploads: {
    maxFileSize: 5 * 1024 * 1024, // 5MB
    allowedMimeTypes: [
      'image/jpeg',
      'image/png',
      'image/gif',
      'application/pdf',
      'text/plain'
    ],
    scanForViruses: process.env.SCAN_UPLOADS === 'true'
  },

  // Cache Control
  cacheControl: {
    default: 'no-store, no-cache, must-revalidate, proxy-revalidate',
    staticAssets: 'public, max-age=31536000, immutable',
    apiResponses: 'no-cache, no-store, must-revalidate'
  }
};

// Helper function to get security configuration
function getSecurityConfig() {
  const config = module.exports;

  // Validate required configuration
  if (!process.env.JWT_SECRET && config.auth.jwt.enabled) {
    throw new Error('JWT_SECRET environment variable is required');
  }

  // Set defaults based on environment
  const isProduction = process.env.NODE_ENV === 'production';
  config.cors.options.credentials = isProduction;
  config.session.cookie.secure = isProduction;
  config.response.enableHSTS = isProduction;

  return config;
}

module.exports.getSecurityConfig = getSecurityConfig;

// Security Test Suite for Express Application
// Tests for OWASP Top 10 vulnerabilities and security best practices

const request = require('supertest');
const app = require('./app.js');

describe('Security Tests', () => {
  // Test 1: Authentication Required for Protected Routes
  describe('Authentication & Authorization', () => {
    test('GET /users without authentication should return 401', async () => {
      const response = await request(app)
        .get('/users')
        .expect('Content-Type', /json/)
        .expect(401);

      expect(response.body).toHaveProperty('error');
      expect(response.body.error).toBe('Authentication required');
    });

    test('GET /users with invalid token should return 403', async () => {
      const response = await request(app)
        .get('/users')
        .set('Authorization', 'Bearer invalid-token')
        .expect('Content-Type', /json/)
        .expect(403);

      expect(response.body).toHaveProperty('error');
      expect(response.body.error).toBe('Invalid token');
    });
  });

  // Test 2: Rate Limiting
  describe('Rate Limiting', () => {
    test('Should enforce rate limits', async () => {
      // Make more requests than allowed by rate limit
      for (let i = 0; i < 110; i++) {
        const response = await request(app).get('/health');
        if (i >= 100) {
          // After exceeding limit, should get 429
          expect(response.status).toBe(429);
          expect(response.body).toHaveProperty('error');
          expect(response.body.error).toBe('Too many requests from this IP, please try again later.');
        }
      }
    }, 30000); // Longer timeout for multiple requests
  });

  // Test 3: Input Validation
  describe('Input Validation', () => {
    test('POST /users with invalid email should return 400', async () => {
      const response = await request(app)
        .post('/users')
        .set('Authorization', 'Bearer test-token')
        .send({
          name: 'Test',
          email: 'invalid-email',
          password: 'Password123!'
        })
        .expect('Content-Type', /json/)
        .expect(400);

      expect(response.body).toHaveProperty('errors');
    });

    test('POST /users with weak password should return 400', async () => {
      const response = await request(app)
        .post('/users')
        .set('Authorization', 'Bearer test-token')
        .send({
          name: 'Test',
          email: 'test@example.com',
          password: 'weak'
        })
        .expect('Content-Type', /json/)
        .expect(400);

      expect(response.body).toHaveProperty('errors');
    });
  });

  // Test 4: Security Headers
  describe('Security Headers', () => {
    test('All responses should include security headers', async () => {
      const response = await request(app)
        .get('/health')
        .expect(200);

      // Check for important security headers
      expect(response.headers).toHaveProperty('x-content-type-options');
      expect(response.headers['x-content-type-options']).toBe('nosniff');

      expect(response.headers).toHaveProperty('x-frame-options');
      expect(response.headers['x-frame-options']).toBe('DENY');

      expect(response.headers).toHaveProperty('referrer-policy');
      expect(response.headers['referrer-policy']).toBe('strict-origin-when-cross-origin');

      // X-Powered-By should not be present
      expect(response.headers).not.toHaveProperty('x-powered-by');
    });
  });

  // Test 5: Injection Attacks
  describe('Injection Prevention', () => {
    test('Should sanitize HTML in query parameters', async () => {
      const response = await request(app)
        .get('/users?search=<script>alert("xss")</script>')
        .set('Authorization', 'Bearer test-token')
        .expect(200);

      // The script tags should be removed or escaped
      expect(response.body.data).toBeDefined();
    });

    test('Should sanitize HTML in request body', async () => {
      const response = await request(app)
        .post('/users')
        .set('Authorization', 'Bearer test-token')
        .send({
          name: '<script>Test</script>',
          email: 'test@example.com',
          password: 'Password123!'
        })
        .expect(400); // Should fail validation due to script tags

      expect(response.body).toHaveProperty('errors');
    });
  });

  // Test 6: CSRF Protection
  describe('CORS Configuration', () => {
    test('Should allow requests from configured origins', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'http://localhost:3000')
        .expect(200);

      expect(response.headers).toHaveProperty('access-control-allow-origin');
    });

    test('Should not allow requests from unconfigured origins', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'http://evil.com')
        .expect(200); // Still returns 200, but CORS headers won't match

      expect(response.headers['access-control-allow-origin']).not.toBe('http://evil.com');
    });
  });

  // Test 7: Error Handling
  describe('Error Handling', () => {
    test('Should not expose stack traces in production', async () => {
      // Simulate production environment
      process.env.NODE_ENV = 'production';

      // Trigger an error (non-existent route)
      const response = await request(app)
        .get('/non-existent-route')
        .expect(404);

      expect(response.body.error).toBe('Not Found');
      expect(response.body.message).not.toContain('Error:');
      expect(response.body.message).not.toContain('at ');

      // Reset environment
      delete process.env.NODE_ENV;
    });

    test('Should handle malformed JSON gracefully', async () => {
      const response = await request(app)
        .post('/users')
        .set('Authorization', 'Bearer test-token')
        .set('Content-Type', 'application/json')
        .send('invalid json')
        .expect(400);

      expect(response.body).toHaveProperty('error');
    });
  });

  // Test 8: Data Exposure Prevention
  describe('Data Protection', () => {
    test('Should paginate user data', async () => {
      const response = await request(app)
        .get('/users?limit=1')
        .set('Authorization', 'Bearer test-token')
        .expect(200);

      expect(response.body).toHaveProperty('data');
      expect(response.body).toHaveProperty('pagination');
      expect(response.body.pagination).toHaveProperty('limit');
      expect(response.body.pagination).toHaveProperty('total');

      // Limit should be capped
      const response2 = await request(app)
        .get('/users?limit=200') // Request more than cap
        .set('Authorization', 'Bearer test-token')
        .expect(200);

      expect(response2.body.pagination.limit).toBeLessThanOrEqual(100);
    });
  });

  // Test 9: Logging
  describe('Logging Security', () => {
    test('Should not log sensitive data', async () => {
      // This test would require intercepting console.log
      // For now, we'll just verify the logging middleware exists
      const response = await request(app)
        .get('/health')
        .expect(200);

      // Response should be successful
      expect(response.body.status).toBe('ok');
    });
  });

  // Test 10: Request Size Limits
  describe('Request Size Limits', () => {
    test('Should reject oversized request bodies', async () => {
      const largeBody = {
        data: 'x'.repeat(20 * 1024 * 1024) // 20MB
      };

      const response = await request(app)
        .post('/users')
        .set('Authorization', 'Bearer test-token')
        .send(largeBody)
        .expect(413); // Payload Too Large

      expect(response.body).toHaveProperty('error');
    });
  });
});

// Additional security-focused tests
describe('Advanced Security Tests', () => {
  // Test for HTTP verb tampering
  test('Should handle unsupported HTTP methods', async () => {
    const response = await request(app)
      .trace('/users')
      .expect(404); // Should be caught by 404 handler

    expect(response.body.error).toBe('Not Found');
  });

  // Test for directory traversal attempts
  test('Should block directory traversal attempts', async () => {
    const response = await request(app)
      .get('/../etc/passwd')
      .expect(404);

    expect(response.body.error).toBe('Not Found');
  });

  // Test for SQL injection patterns (if applicable)
  test('Should sanitize SQL injection patterns', async () => {
    const response = await request(app)
      .get('/users?search=1%27%20OR%20%271%27%3D%271')
      .set('Authorization', 'Bearer test-token')
      .expect(200);

    // Should not crash or expose errors
    expect(response.body).toHaveProperty('data');
  });
});

// Helper function to generate test tokens
function generateTestToken() {
  // In a real test environment, use actual JWT generation
  return process.env.TEST_API_TOKEN || 'test-token';
}

// Export for use in other test files
module.exports = {
  generateTestToken
};

