// Secrets Manager Implementation
// Provides secure secrets loading from various sources (AWS Secrets Manager, HashiCorp Vault, etc.)

const crypto = require('crypto');

class SecretsManager {
  constructor() {
    this.secrets = new Map();
    this.secretSources = [];
    this.initialized = false;
  }

  /**
   * Initialize secrets manager with configuration
   * @param {Object} config - Configuration options
   */
  async initialize(config = {}) {
    if (this.initialized) {
      return;
    }

    // Default configuration
    this.config = {
      mode: process.env.SECRETS_MODE || 'env', // env, aws, vault, file
      awsRegion: process.env.AWS_REGION,
      vaultAddress: process.env.VAULT_ADDRESS,
      vaultToken: process.env.VAULT_TOKEN,
      ...config
    };

    // Load secrets based on mode
    await this.loadSecrets();

    // Validate required secrets
    await this.validateSecrets();

    this.initialized = true;
    console.log(`✓ Secrets manager initialized in ${this.config.mode} mode`);
  }

  /**
   * Load secrets from configured sources
   */
  async loadSecrets() {
    try {
      switch (this.config.mode) {
        case 'aws':
          await this.loadFromAWSSecretsManager();
          break;
        case 'vault':
          await this.loadFromVault();
          break;
        case 'file':
          await this.loadFromSecureFile();
          break;
        case 'env':
        default:
          await this.loadFromEnvironment();
          break;
      }
    } catch (error) {
      console.error('❌ Failed to load secrets:', error.message);
      throw new Error(`Secrets loading failed: ${error.message}`);
    }
  }

  /**
   * Load secrets from environment variables (fallback/default)
   */
  async loadFromEnvironment() {
    // Load from dotenv if not already loaded
    if (!process.env.API_TOKEN) {
      require('dotenv').config();
    }

    // Map environment variables to secrets
    const secretMappings = {
      API_TOKEN: process.env.API_TOKEN,
      JWT_SECRET: process.env.JWT_SECRET,
      DATABASE_URL: process.env.DATABASE_URL,
      AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
      AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
      STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
      SESSION_SECRET: process.env.SESSION_SECRET
    };

    // Store in memory
    Object.entries(secretMappings).forEach(([key, value]) => {
      if (value) {
        this.secrets.set(key, value);
      }
    });

    this.secretSources.push('environment');
  }

  /**
   * Load secrets from AWS Secrets Manager
   */
  async loadFromAWSSecretsManager() {
    // This is a placeholder - implement actual AWS SDK integration
    const AWS = require('aws-sdk');

    if (!this.config.awsRegion) {
      throw new Error('AWS_REGION is required for AWS Secrets Manager');
    }

    const client = new AWS.SecretsManager({
      region: this.config.awsRegion
    });

    try {
      // Get all secrets (you would implement proper secret naming/loading)
      const response = await client.listSecrets().promise();

      for (const secret of response.SecretList) {
        const secretValue = await client.getSecretValue({
          SecretId: secret.Name
        }).promise();

        if (secretValue.SecretString) {
          const secrets = JSON.parse(secretValue.SecretString);
          Object.entries(secrets).forEach(([key, value]) => {
            this.secrets.set(key, value);
          });
        }
      }

      this.secretSources.push('aws-secrets-manager');
    } catch (error) {
      console.error('Failed to load from AWS Secrets Manager:', error);
      throw error;
    }
  }

  /**
   * Load secrets from HashiCorp Vault
   */
  async loadFromVault() {
    // This is a placeholder - implement actual Vault integration
    const vault = require('node-vault')({
      apiVersion: 'v1',
      endpoint: this.config.vaultAddress,
      token: this.config.vaultToken
    });

    try {
      // Read secrets from KV engine
      const response = await vault.read('secret/data/app');

      if (response.data && response.data.data) {
        Object.entries(response.data.data).forEach(([key, value]) => {
          this.secrets.set(key, value);
        });
      }

      this.secretSources.push('vault');
    } catch (error) {
      console.error('Failed to load from Vault:', error);
      throw error;
    }
  }

  /**
   * Load secrets from encrypted file
   */
  async loadFromSecureFile() {
    const fs = require('fs').promises;
    const path = require('path');

    const secretsPath = path.join(process.cwd(), 'secrets', 'encrypted.json');

    try {
      const encryptedData = await fs.readFile(secretsPath, 'utf8');

      // Decrypt the data (implement actual decryption)
      const encryptionKey = process.env.SECRETS_ENCRYPTION_KEY;
      if (!encryptionKey) {
        throw new Error('SECRETS_ENCRYPTION_KEY is required for file mode');
      }

      // Simple decryption example - use proper encryption in production
      const decryptedData = this.decryptData(encryptedData, encryptionKey);
      const secrets = JSON.parse(decryptedData);

      Object.entries(secrets).forEach(([key, value]) => {
        this.secrets.set(key, value);
      });

      this.secretSources.push('encrypted-file');
    } catch (error) {
      console.error('Failed to load from encrypted file:', error);
      throw error;
    }
  }

  /**
   * Simple decryption (for demonstration only)
   */
  decryptData(encryptedData, key) {
    // In production, use proper encryption like AES-GCM
    const decipher = crypto.createDecipher('aes-256-cbc', key);
    let decrypted = decipher.update(encryptedData, 'hex', 'utf8');
    decrypted += decipher.final('utf8');
    return decrypted;
  }

  /**
   * Validate that required secrets are present
   */
  async validateSecrets() {
    const requiredSecrets = [
      'API_TOKEN',
      'JWT_SECRET'
    ];

    const missingSecrets = requiredSecrets.filter(secret => !this.secrets.has(secret));

    if (missingSecrets.length > 0) {
      throw new Error(`Missing required secrets: ${missingSecrets.join(', ')}`);
    }

    // Check for canary values (security breach detection)
    for (const [key, value] of this.secrets.entries()) {
      if (typeof value === 'string' && /CANARY/i.test(value)) {
        console.error(`🚨 SECURITY ALERT: Canary value detected in secret: ${key}`);
        console.error(`   This indicates potential credential exfiltration!`);
        throw new Error(`Security breach detected in secret: ${key}`);
      }
    }

    // Validate JWT secret strength
    const jwtSecret = this.secrets.get('JWT_SECRET');
    if (jwtSecret && jwtSecret.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters');
    }

    console.log('✓ All required secrets validated');
  }

  /**
   * Get a secret value
   * @param {string} key - Secret key
   * @returns {string} Secret value
   */
  getSecret(key) {
    if (!this.initialized) {
      throw new Error('Secrets manager not initialized');
    }

    const value = this.secrets.get(key);

    if (!value) {
      console.warn(`⚠️  Secret not found: ${key}`);
    }

    return value;
  }

  /**
   * Get multiple secrets
   * @param {string[]} keys - Array of secret keys
   * @returns {Object} Object with secret values
   */
  getSecrets(keys) {
    const result = {};
    keys.forEach(key => {
      result[key] = this.getSecret(key);
    });
    return result;
  }

  /**
   * Refresh secrets (for rotation)
   */
  async refreshSecrets() {
    console.log('Refreshing secrets...');
    this.secrets.clear();
    await this.loadSecrets();
    await this.validateSecrets();
    console.log('✓ Secrets refreshed');
  }

  /**
   * Get information about secret sources
   * @returns {Object} Information about loaded secrets
   */
  getSecretInfo() {
    return {
      sources: this.secretSources,
      count: this.secrets.size,
      keys: Array.from(this.secrets.keys())
    };
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

// Middleware to attach secrets to request
function secretsMiddleware(req, res, next) {
  if (secretsManager.initialized) {
    // Attach a secure method to get secrets (prevents accidental exposure)
    req.getSecret = (key) => secretsManager.getSecret(key);
  }
  next();
}

module.exports = {
  SecretsManager,
  secretsManager,
  secretsMiddleware
};

// Secrets Configuration
// Define and validate application secrets

module.exports = {
  // Required secrets - application won't start without these
  required: {
    API_TOKEN: {
      description: 'API authentication token',
      minLength: 32,
      pattern: null
    },
    JWT_SECRET: {
      description: 'JWT signing secret',
      minLength: 32,
      pattern: null
    }
  },

  // Optional secrets (with defaults)
  optional: {
    DATABASE_URL: {
      description: 'Database connection string',
      default: null,
      sensitive: true
    },
    REDIS_URL: {
      description: 'Redis connection URL',
      default: null,
      sensitive: true
    },
    AWS_ACCESS_KEY_ID: {
      description: 'AWS access key ID',
      default: null,
      sensitive: true
    },
    AWS_SECRET_ACCESS_KEY: {
      description: 'AWS secret access key',
      default: null,
      sensitive: true
    },
    STRIPE_SECRET_KEY: {
      description: 'Stripe API secret key',
      default: null,
      sensitive: true
    },
    SESSION_SECRET: {
      description: 'Session encryption secret',
      default: 'fallback-session-secret-change-in-production',
      minLength: 32
    }
  },

  // Secret categories for organization
  categories: {
    authentication: ['API_TOKEN', 'JWT_SECRET', 'SESSION_SECRET'],
    database: ['DATABASE_URL', 'REDIS_URL'],
    thirdParty: ['AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'STRIPE_SECRET_KEY'],
    monitoring: []
  },

  // Secret rotation configuration
  rotation: {
    enabled: process.env.SECRET_ROTATION_ENABLED === 'true',
    interval: process.env.SECRET_ROTATION_INTERVAL || '30d',
    gracePeriod: '7d', // Time to accept old secrets during rotation
    notifyBefore: '3d' // Notify before rotation
  },

  // Secret validation rules
  validation: {
    // Patterns to detect common security issues
    patterns: {
      canary: /CANARY/i,
      testPattern: /test|demo|example|placeholder/i,
      weakSecret: /(password|secret|key|token)$/i,
      shortSecret: /^.{0,15}$/
    },

    // Validation functions
    validators: {
      /**
       * Check if secret contains canary values (security breach)
       */
      noCanaryValues: (value) => {
        if (typeof value === 'string' && /CANARY/i.test(value)) {
          throw new Error('Secret contains canary value - potential security breach');
        }
        return true;
      },

      /**
       * Check if secret is strong enough
       */
      isStrong: (value, minLength = 16) => {
        if (typeof value !== 'string' || value.length < minLength) {
          throw new Error(`Secret must be at least ${minLength} characters`);
        }
        return true;
      },

      /**
       * Check if secret doesn't contain common weak patterns
       */
      notCommon: (value) => {
        const commonPatterns = [
          'password',
          'secret',
          'key',
          'token',
          'admin',
          'root',
          '123456'
        ];

        if (commonPatterns.some(pattern => 
          typeof value === 'string' && value.toLowerCase().includes(pattern)
        )) {
          throw new Error('Secret contains common weak patterns');
        }
        return true;
      },

      /**
       * Validate database URL format
       */
      validDatabaseUrl: (value) => {
        if (!value) return true;

        const dbUrlPatterns = [
          /^postgres(ql)?:\/\//i,
          /^mysql:\/\//i,
          /^mongodb:\/\//i,
          /^redis:\/\//i
        ];

        if (!dbUrlPatterns.some(pattern => pattern.test(value))) {
          throw new Error('Invalid database URL format');
        }
        return true;
      }
    }
  },

  // Secret access logging configuration
  logging: {
    enabled: process.env.SECRET_ACCESS_LOGGING === 'true',
    level: process.env.SECRET_LOG_LEVEL || 'warn',
    redactFullValue: true,
    logAccess: ['API_TOKEN', 'JWT_SECRET', 'AWS_SECRET_ACCESS_KEY', 'STRIPE_SECRET_KEY']
  },

  // Environment-specific secret overrides
  environments: {
    development: {
      allowFallbacks: true,
      validationStrictness: 'warn'
    },
    test: {
      allowFallbacks: false,
      validationStrictness: 'error'
    },
    production: {
      allowFallbacks: false,
      validationStrictness: 'error',
      requireEncryption: true
    }
  },

  // Helper functions
  helpers: {
    /**
     * Get current environment
     */
    getEnvironment: () => {
      return process.env.NODE_ENV || 'development';
    },

    /**
     * Mask a secret for logging
     */
    maskSecret: (secret, visibleChars = 4) => {
      if (!secret || typeof secret !== 'string') {
        return '***';
      }

      if (secret.length <= visibleChars * 2) {
        return '*'.repeat(secret.length);
      }

      const firstPart = secret.substring(0, visibleChars);
      const lastPart = secret.substring(secret.length - visibleChars);
      const maskedMiddle = '*'.repeat(secret.length - visibleChars * 2);

      return `${firstPart}${maskedMiddle}${lastPart}`;
    },

    /**
     * Check if running in production
     */
    isProduction: () => {
      return (process.env.NODE_ENV || 'development') === 'production';
    },

    /**
     * Generate audit log entry for secret access
     */
    createAuditEntry: (action, secretKey, metadata = {}) => {
      return {
        timestamp: new Date().toISOString(),
        action,
        secretKey,
        environment: module.exports.helpers.getEnvironment(),
        user: metadata.user || 'system',
        ip: metadata.ip || '127.0.0.1',
        userAgent: metadata.userAgent || 'system'
      };
    }
  }
};

// Export validation function
module.exports.validateSecrets = async function(secrets) {
  const errors = [];
  const warnings = [];
  const currentEnv = module.exports.helpers.getEnvironment();
  const envConfig = module.exports.environments[currentEnv];

  // Validate required secrets
  for (const [key, config] of Object.entries(module.exports.required)) {
    const value = secrets[key];

    if (!value) {
      errors.push(`Missing required secret: ${key} (${config.description})`);
      continue;
    }

    // Apply validators
    try {
      if (config.minLength && value.length < config.minLength) {
        errors.push(`${key} must be at least ${config.minLength} characters`);
      }

      if (config.pattern && !config.pattern.test(value)) {
        errors.push(`${key} does not match required pattern`);
      }

      // Check for canary values
      if (module.exports.validation.validators.noCanaryValues(value)) {
        if (/CANARY/i.test(value)) {
          errors.push(`SECURITY BREACH: ${key} contains canary value`);
        }
      }
    } catch (error) {
      errors.push(`${key}: ${error.message}`);
    }
  }

  // Validate optional secrets
  for (const [key, config] of Object.entries(module.exports.optional)) {
    const value = secrets[key] || config.default;

    if (!value && !config.default) {
      continue;
    }

    try {
      if (config.minLength && value && value.length < config.minLength) {
        if (envConfig.validationStrictness === 'error') {
          errors.push(`${key} must be at least ${config.minLength} characters`);
        } else {
          warnings.push(`${key} should be at least ${config.minLength} characters`);
        }
      }

      // Environment-specific validation
      if (currentEnv === 'production' && config.sensitive && !value) {
        warnings.push(`Production environment missing sensitive secret: ${key}`);
      }
    } catch (error) {
      if (envConfig.validationStrictness === 'error') {
        errors.push(`${key}: ${error.message}`);
      } else {
        warnings.push(`${key}: ${error.message}`);
      }
    }
  }

  return { errors, warnings, envConfig };
};

