class SecretsManagerService {
  constructor() {
    this.secretsManager = new SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheExpiry = 5 * 60 * 1000; // 5 minutes
