        databaseUrl: this.validateEnv('DATABASE_URL', 'string'),
        jwtSecret: this.validateEnv('JWT_SECRET', 'string', 32),
        apiKey: this.validateEnv('API_KEY', 'string')
      };

      this.secrets.set('database', devSecrets);
    }
  }

  validateEnv(name, type, minLength = null) {
    const value = process.env[name];

    if (!value) {
      throw new Error(`Missing required environment variable: ${name}`);
    }

    if (type === 'string' && minLength && value.length < minLength) {
      throw new Error(`Environment variable ${name} must be at least ${minLength} characters`);
    }

    return value;
  }

  get(key) {
    const secret = this.secrets.get(key);
    if (!secret) {
      throw new Error(`Secret ${key} not found`);
    }
    return secret;
  }
}

module.exports = new SecretManager();
