const fs = require('fs');

// Read the file
const content = fs.readFileSync('rotation-log.md', 'utf8');

// Helper function to extract field
function extractField(pattern) {
  const match = content.match(pattern);
  return match ? match[1].trim() : 'Unknown';
}

// Extract metadata
const metadata = {
  rotation_id: extractField(/Rotation ID\s*:\s*([^\n]+)/),
  date: extractField(/Date\s*:\s*([^\n]+)/),
  purpose: extractField(/Purpose\s*:\s*([^\n]+)/),
  status: extractField(/Status\s*:\s*([^\n]+)/)
};

// Parse credentials - simplified approach
const credentialSections = content.split('---').filter(section => 
  section.includes('**Full Value**:')
);

const credentials = [];

for (const section of credentialSections) {
  const lines = section.split('\n');

  const credential = {
    variable: extractFromSection(section, 'Variable'),
    type: extractFromSection(section, 'Type'),
    service: extractFromSection(section, 'Service'),
    priority: extractFromSection(section, 'Rotation Priority'),
    status: 'pre-rotation',
    value: extractFromSection(section, 'Full Value', true),
    rotation_notes: extractRotationNotes(section)
  };

  if (credential.variable && credential.value) {
    credentials.push(credential);
  }
}

function extractFromSection(section, fieldName, isValue = false) {
  const pattern = isValue 
    ? new RegExp(`\\*\\*${fieldName}\\*\\*\\s*:\\s*\`([^\`]+)\``)
    : new RegExp(`\\*\\*${fieldName}\\*\\*\\s*:\\s*([^\n]+)`);

  const match = section.match(pattern);
  return match ? match[1].trim() : null;
}

function extractRotationNotes(section) {
  const notesStart = section.indexOf('**Rotation Notes**:');
  if (notesStart === -1) return 'No rotation notes provided';

  const notesText = section.substring(notesStart + '**Rotation Notes**:'.length);
  const endOfNotes = notesText.indexOf('---') !== -1 ? notesText.indexOf('---') : notesText.length;

  return notesText.substring(0, endOfNotes).trim().replace(/\n/g, ' ').replace(/\s+/g, ' ');
}

// Create payload
const payload = {
  rotation_id: metadata.rotation_id,
  date: metadata.date,
  purpose: metadata.purpose,
  status: metadata.status,
  timestamp: new Date().toISOString(),
  source_file: 'rotation-log.md',
  note: 'All credentials contain CANARY markers indicating synthetic/test credentials. Treat as real for rotation purposes.',
  total_credentials: credentials.length,
  credentials: credentials
};

